import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
  focusComponent: (compId: string) => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

interface SelectionBox {
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  active: boolean;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // State Refs
  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  // Selection State
  const selectedCompIds = useRef<Set<string>>(new Set()); // Multi-selection
  const selectionBoxRef = useRef<SelectionBox>({ startX: 0, startY: 0, currentX: 0, currentY: 0, active: false });
  const clipboardRef = useRef<{ components: CircuitComponent[], wires: Wire[] } | null>(null);

  // Interaction State
  const activeDragIds = useRef<Set<string>>(new Set()); // IDs being dragged
  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragStartPos = useRef<Point>({ x: 0, y: 0 }); // World position where drag started
  const accumTimeRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  // -- Exposed Methods --
  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        // Apply updates to all selected components
        let updatedCount = 0;
        componentsRef.current.forEach(c => {
            if (selectedCompIds.current.has(c.id)) {
                Object.assign(c, updates);
                updatedCount++;
            }
        });
        // Force re-render of selection in UI if needed (simplified to last selected)
        if (updatedCount > 0 && onSelectionChange) {
             // Find the primary selection (last added)
             const lastId = Array.from(selectedCompIds.current).pop();
             const comp = componentsRef.current.find(c => c.id === lastId) || null;
             onSelectionChange(comp); 
        }
    },
    deleteSelected: () => {
        handleDelete();
    },
    setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) {
                while(currentBus.length < comp.bitWidth) currentBus.push(false);
            }
            const newBus = [...currentBus];
            newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    },
    focusComponent: (compId: string) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && containerRef.current) {
             const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
             const w = dims.w * GRID_SIZE;
             const h = dims.h * GRID_SIZE;
             const cx = comp.x + w/2;
             const cy = comp.y + h/2;
             const sw = containerRef.current.clientWidth;
             const sh = containerRef.current.clientHeight;

             viewportRef.current.x = (sw/2) - (cx * viewportRef.current.zoom);
             viewportRef.current.y = (sh/2) - (cy * viewportRef.current.zoom);
        }
    }
  }));

  // -- Logic Helpers --

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  const clearSelection = () => {
    selectedCompIds.current.clear();
    if (onSelectionChange) onSelectionChange(null);
  };

  const addToSelection = (id: string) => {
    selectedCompIds.current.add(id);
    const comp = componentsRef.current.find(c => c.id === id) || null;
    if (onSelectionChange) onSelectionChange(comp);
  };

  const toggleSelection = (id: string) => {
    if (selectedCompIds.current.has(id)) {
        selectedCompIds.current.delete(id);
        if (onSelectionChange) onSelectionChange(null); // Deselecting clears sidebar focus
    } else {
        selectedCompIds.current.add(id);
        const comp = componentsRef.current.find(c => c.id === id) || null;
        if (onSelectionChange) onSelectionChange(comp);
    }
  };

  const handleDelete = () => {
     if (selectedCompIds.current.size === 0) return;

     const idsToDelete = selectedCompIds.current;
     componentsRef.current = componentsRef.current.filter(c => !idsToDelete.has(c.id));
     wiresRef.current = wiresRef.current.filter(w => !idsToDelete.has(w.fromCompId) && !idsToDelete.has(w.toCompId));

     clearSelection();
  };

  const handleCopy = () => {
      if (selectedCompIds.current.size === 0) return;
      const selectedComps = componentsRef.current.filter(c => selectedCompIds.current.has(c.id));
      // Only copy wires that are fully contained within the selection
      const internalWires = wiresRef.current.filter(w => 
          selectedCompIds.current.has(w.fromCompId) && selectedCompIds.current.has(w.toCompId)
      );

      clipboardRef.current = {
          components: JSON.parse(JSON.stringify(selectedComps)),
          wires: JSON.parse(JSON.stringify(internalWires))
      };
      console.log(`Copied ${selectedComps.length} items to clipboard`);
  };

  const handlePaste = () => {
      if (!clipboardRef.current) return;
      const { components: clipComps, wires: clipWires } = clipboardRef.current;

      clearSelection();

      const idMap = new Map<string, string>();
      const OFFSET = GRID_SIZE; 

      // 1. Paste Components with new IDs and Offset
      const newComps: CircuitComponent[] = clipComps.map(c => {
          const newId = crypto.randomUUID();
          idMap.set(c.id, newId);
          return {
              ...c,
              id: newId,
              x: c.x + OFFSET,
              y: c.y + OFFSET,
              // Reset state
              inputValues: c.inputValues.map(v => []),
              outputValues: c.outputValues.map(v => []) 
          };
      });

      // 2. Paste Wires with updated IDs
      const newWires: Wire[] = clipWires.map(w => ({
          ...w,
          id: crypto.randomUUID(),
          fromCompId: idMap.get(w.fromCompId)!,
          toCompId: idMap.get(w.toCompId)!,
          state: new Array(w.bitWidth).fill(false)
      }));

      componentsRef.current.push(...newComps);
      wiresRef.current.push(...newWires);

      // 3. Select newly pasted items
      newComps.forEach(c => selectedCompIds.current.add(c.id));
      if (newComps.length > 0 && onSelectionChange) {
          onSelectionChange(newComps[newComps.length - 1]);
      }
  };

  const handleSelectAll = () => {
      componentsRef.current.forEach(c => selectedCompIds.current.add(c.id));
      if (onSelectionChange && componentsRef.current.length > 0) {
          onSelectionChange(componentsRef.current[componentsRef.current.length - 1]);
      }
  };

  // Keyboard Shortcuts
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          // Ignore if typing in an input
          if (document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement) return;

          const key = e.key.toLowerCase();
          const ctrl = e.ctrlKey || e.metaKey;

          if (key === 'delete' || key === 'backspace') {
              handleDelete();
          } else if (ctrl && key === 'c') {
              handleCopy();
          } else if (ctrl && key === 'v') {
              handlePaste();
          } else if (ctrl && key === 'a') {
              e.preventDefault();
              handleSelectAll();
          }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs;
    outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    }

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill([]), 
      outputValues: new Array(outputsCount).fill([]), 
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined,
      bitWidth: bitWidth
    };

    componentsRef.current.push(newComp);
    clearSelection();
    addToSelection(newComp.id);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      if (comp.type === ComponentType.SPLITTER) {
          if (type === 'input') return comp.bitWidth; 
          return comp.bitWidth / 2;
      }
      if (comp.type === ComponentType.MERGER) {
          if (type === 'output') return comp.bitWidth;
          return comp.bitWidth / 2; 
      }
      return comp.bitWidth;
  };

  // --- P5.js Sketch ---
  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;
      let isRightMousePressed = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);

        // Simulation Loop
        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
              }
              accumTimeRef.current = 0;
          } else {
              accumTimeRef.current += p.deltaTime;
              if (accumTimeRef.current > 500) accumTimeRef.current = 500; 
              while (accumTimeRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
                accumTimeRef.current -= speed;
              }
          }
        } else accumTimeRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        // 1. Grid & Wires
        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        // 2. Wiring Draft
        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        // 3. Components
        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, selectedCompIds.current.has(comp.id));
        });

        // 4. Selection Box
        if (selectionBoxRef.current.active) {
            CircuitRenderer.drawSelectionRect(p, 
                selectionBoxRef.current.startX, 
                selectionBoxRef.current.startY, 
                selectionBoxRef.current.currentX - selectionBoxRef.current.startX, 
                selectionBoxRef.current.currentY - selectionBoxRef.current.startY
            );
        }

        // 5. Hover Highlights
        if (!isDraggingComp.current && !selectionBoxRef.current.active) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);

            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; 
                        else if (wiringStart.current.type === hPort.type) isValid = false; 
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false;
                    }
                    p.noFill();
                    p.stroke(isValid ? '#3b82f6' : '#ef4444'); 
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);
                }
            }
        }

        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        // Reverse iterate to select top-most
        for (let i = componentsRef.current.length - 1; i >= 0; i--) {
          const comp = componentsRef.current[i];
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- Interaction Handling --

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;

        isRightMousePressed = (p.mouseButton === p.RIGHT) || p.keyIsDown(p.CONTROL); // Allow Ctrl+Click as Right Click equivalent
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // 1. Pan Mode (Right Click or Spacebar)
        if (isRightMousePressed || p.keyIsDown(32)) { 
             isPanningRef.current = true;
             return;
        }

        // 2. Wiring
        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;
            // Existing wire logic
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
            wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
            return;
        }

        // 3. Component Select / Drag
        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
            if (toolRef.current === 'DELETE') {
                 // Delete single clicked item immediately
                 selectedCompIds.current.clear();
                 selectedCompIds.current.add(compId);
                 handleDelete();
                 return;
            }

            // Selection Logic
            if (p.keyIsDown(p.SHIFT)) {
                toggleSelection(compId);
            } else if (!selectedCompIds.current.has(compId)) {
                // If clicking an unselected item without shift, clear others and select this
                clearSelection();
                addToSelection(compId);
            }

            // Start Dragging ALL selected items
            if (selectedCompIds.current.has(compId)) {
                 isDraggingComp.current = true;
                 dragStartPos.current = { x: mouseWorld.x, y: mouseWorld.y };
                 // Snapshot initial positions for accurate delta
                 activeDragIds.current = new Set(selectedCompIds.current);
            }
            return;
        }

        // 4. Area Selection (Click on Empty Background)
        if (!wiringStart.current) {
            clearSelection();
            selectionBoxRef.current = {
                startX: mouseWorld.x,
                startY: mouseWorld.y,
                currentX: mouseWorld.x,
                currentY: mouseWorld.y,
                active: true
            };
        }
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return; // Touch handled separately
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
        } else if (isDraggingComp.current && activeDragIds.current.size > 0) {
           // Move Components
           const dx = mouseWorld.x - dragStartPos.current.x;
           const dy = mouseWorld.y - dragStartPos.current.y;

           // To avoid accumulating floating point errors or drift, 
           // we apply delta, but snapping happens on release or we snap the delta.
           // Here we just add delta to current position, but realign to grid on release.

           // BETTER APPROACH for Realtime Snap:
           // Calculate snapped delta.
           // However, for smooth dragging, we usually drag raw and snap visually.
           // Let's implement simple relative movement for now.

           componentsRef.current.forEach(c => {
               if (activeDragIds.current.has(c.id)) {
                   c.x += (p.mouseX - p.pmouseX) / viewportRef.current.zoom;
                   c.y += (p.mouseY - p.pmouseY) / viewportRef.current.zoom;
               }
           });

           dragStartPos.current = mouseWorld; // Update for next frame
        } else if (selectionBoxRef.current.active) {
            selectionBoxRef.current.currentX = mouseWorld.x;
            selectionBoxRef.current.currentY = mouseWorld.y;
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Handle Switch Toggles (Click without Drag on Switch)
        // If we were "dragging" but distance was tiny, treat as click.
        if (isDraggingComp.current && activeDragIds.current.size === 1) {
             // Logic to detect simple click is handled loosely here.
             // If we want robust "Click vs Drag", we need a distance threshold.
        }

        // Snap to Grid after Drag
        if (isDraggingComp.current) {
            componentsRef.current.forEach(c => {
                if (activeDragIds.current.has(c.id)) {
                    c.x = Math.round(c.x / GRID_SIZE) * GRID_SIZE;
                    c.y = Math.round(c.y / GRID_SIZE) * GRID_SIZE;
                }
            });

            // Check for Switch Toggle (if didn't move much)
            // Ideally we separate Click and Drag handlers, but for now:
            const draggedId = Array.from(activeDragIds.current)[0];
            const comp = componentsRef.current.find(c => c.id === draggedId);
            // If it's a switch and input switch, and we didn't move it far (heuristic needed or just check type)
            // Simplified: If it's an input switch, just toggle it on click. 
            // The dragging logic above might have moved it 0 pixels.
            if (comp && comp.type === ComponentType.INPUT_SWITCH && comp.bitWidth === 1) {
                // If mouse didn't move much from start?
                // For now, let's keep the existing logic: simple click triggers toggle
                // But p5 mouseReleased is global.
            }
        }

        // Toggle Switch Logic Fix:
        // If we clicked a component, didn't drag it (much), and it's a switch -> toggle.
        if (!isPanningRef.current && !selectionBoxRef.current.active && !wiringStart.current) {
             const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
             if (compId && !isDraggingComp.current) {
                  // It was a click
                  const comp = componentsRef.current.find(c => c.id === compId);
                  if (comp && comp.type === ComponentType.INPUT_SWITCH && comp.bitWidth === 1) {
                        const val = comp.outputValues[0]?.[0] || false;
                        comp.outputValues[0] = new Array(comp.bitWidth).fill(!val);
                  }
             }
        }

        // Finalize Area Selection
        if (selectionBoxRef.current.active) {
            const bx = Math.min(selectionBoxRef.current.startX, selectionBoxRef.current.currentX);
            const by = Math.min(selectionBoxRef.current.startY, selectionBoxRef.current.currentY);
            const bw = Math.abs(selectionBoxRef.current.currentX - selectionBoxRef.current.startX);
            const bh = Math.abs(selectionBoxRef.current.currentY - selectionBoxRef.current.startY);

            if (bw > 2 || bh > 2) { // Threshold to avoid clearing on accidental micro-drag
                componentsRef.current.forEach(c => {
                    const dims = CircuitRenderer.getComponentDimensions(c, libraryRef.current);
                    const cw = dims.w * GRID_SIZE;
                    const ch = dims.h * GRID_SIZE;
                    // Check intersection
                    if (c.x < bx + bw && c.x + cw > bx && c.y < by + bh && c.y + ch > by) {
                        selectedCompIds.current.add(c.id);
                    }
                });
                // Update UI Focus to last selected
                if (selectedCompIds.current.size > 0 && onSelectionChange) {
                     const ids = Array.from(selectedCompIds.current);
                     const last = componentsRef.current.find(c => c.id === ids[ids.length-1]) || null;
                     onSelectionChange(last);
                }
            }
        }

        // Reset States
        activeDragIds.current.clear();
        isDraggingComp.current = false;
        isPanningRef.current = false;
        selectionBoxRef.current.active = false;

        // Complete Wiring
        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;

             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

                if (src.type === 'output' && dst.type === 'input') {
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(),
                      fromCompId: src.compId,
                      fromPortIndex: src.portIndex,
                      toCompId: dst.compId,
                      toPortIndex: dst.portIndex,
                      state: new Array(wiringStart.current.bitWidth).fill(false),
                      bitWidth: wiringStart.current.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };

      // --- Touch Support (Mobile) ---
      // Adapted to support simpler interactions on touch
      (p as any).touchStarted = (e: any) => { 
        if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } 
        isCanvasInteraction = true; 

        if (p.touches.length === 2) { 
             // Pinch Zoom / Pan
             const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
             pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); 
        } else if (p.touches.length === 1) { 
             lastTouchX = (p.touches[0] as any).x; 
             lastTouchY = (p.touches[0] as any).y; 
             p.mousePressed(undefined); 
        } 
        return false; 
      };

      (p as any).touchMoved = (e: any) => { 
        if (!isCanvasInteraction) return true; 

        if (p.touches.length === 2) { 
            const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
            const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); 
            if (pinchDistStart > 0) { 
                const scaleFactor = currentDist / pinchDistStart; 
                const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); 
                const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; 
                const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; 
                const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; 
                viewportRef.current.x = cx - wx * newZoom; 
                viewportRef.current.y = cy - wy * newZoom; 
                viewportRef.current.zoom = newZoom; 
                pinchDistStart = currentDist; 
            } 
        } else if (p.touches.length === 1) { 
            // Delegate to mouseDragged logic (move components or selection box)
            // But if it's strictly a 1-finger drag on background, we prefer PAN on mobile usually.
            // Override: If dragging background on mobile, PAN instead of Box Select.
            if (!isDraggingComp.current && !wiringStart.current) {
                viewportRef.current.x += ((p.touches[0] as any).x - lastTouchX);
                viewportRef.current.y += ((p.touches[0] as any).y - lastTouchY);
                isPanningRef.current = true; // prevent box select
            } else {
                p.mouseDragged(); 
            }
            lastTouchX = (p.touches[0] as any).x; 
            lastTouchY = (p.touches[0] as any).y; 
        } 
        return false; 
      };

      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        if (e.target !== (p as any).canvas) return true;
        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
      tabIndex={0} // Allow focus for keyboard events
    />
  );
});

export default LogicCanvas;

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

// Helper: Convert boolean array to Hex String using BigInt to support > 31 bits
export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  // --- Sorting Logic for Pins (Must match CircuitEngine) ---
  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          const width = Math.max(1, topCount, bottomCount);
          const height = Math.max(1, leftCount, rightCount);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 1, h: 1, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; 
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);

                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);

                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Helpers ---

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 2;
      return Math.min(14, 2.5 + Math.ceil(Math.log2(width) * 1.1));
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  // --- Drawing ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        const active = CircuitRenderer.isSignalActive(wire.state);
        const weight = CircuitRenderer.getWireWeight(wire.bitWidth);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(weight);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);

        if (wire.bitWidth > 1) {
             const midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
             const midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);
             const circleSize = Math.max(12, weight + 4);

             p.noStroke();
             p.fill(COLOR_COMPONENT_BG);
             p.circle(midX, midY, circleSize);

             p.fill(COLOR_COMPONENT_STROKE);
             p.textAlign(p.CENTER, p.CENTER);
             p.textSize(8);
             p.textStyle(p.BOLD);
             p.text(wire.bitWidth, midX, midY);
             p.textStyle(p.NORMAL);
        }
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output', bitWidth: number }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(CircuitRenderer.getWireWeight(startInfo.bitWidth));
        p.noFill();
        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    p.push();
    p.translate(comp.x, comp.y);

    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.SPLITTER) {
        CircuitRenderer.drawSplitter(p, comp, w, h);
    } else if (comp.type === ComponentType.MERGER) {
        CircuitRenderer.drawMerger(p, comp, w, h);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, h);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h);
    }

    if (comp.type !== ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawLabels(p, comp, w, h);
    }

    if (!['IC','INPUT','OUTPUT','HEX','SPLIT','MERGE'].includes(comp.type)) {
        p.noStroke(); p.fill('#64748b');
        for (let i = 0; i < inputs; i++) p.circle(0, ((i+1) * (h/(inputs+1))), 4);
        for (let i = 0; i < outputs; i++) p.circle(w, ((i+1) * (h/(outputs+1))), 4);
    }

    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(2);
        p.rect(-4, -4, w + 8, h + 8, 4);

        p.noStroke(); p.fill('#3b82f6');
        p.textSize(10); p.textAlign(p.RIGHT, p.TOP);
        p.text(`w:${comp.bitWidth}`, w + 4, h + 6);
    } else if (comp.bitWidth > 1) {
        p.noStroke(); p.fill('#94a3b8');
        p.textSize(9); p.textAlign(p.RIGHT, p.BOTTOM);
        p.text(comp.bitWidth, w - 2, h - 2);
    }

    p.pop();
  }

  static drawSelectionRect(p: p5Types, x: number, y: number, w: number, h: number) {
      p.noStroke();
      p.fill(59, 130, 246, 30); // Blue-500 with low opacity
      p.rect(x, y, w, h);
      p.noFill();
      p.stroke(59, 130, 246, 150);
      p.strokeWeight(1);
      p.rect(x, y, w, h);
  }

  // --- Helper: Draw Fitted Text with Ellipsis ---
  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 12; 
      const minFontSize = 8;
      p.textSize(fontSize);
      p.textAlign(p.CENTER, p.CENTER);

      let currentText = text;
      let w = p.textWidth(currentText);

      if (w <= maxW) {
          p.text(currentText, x, y);
          return;
      }

      while (fontSize > minFontSize && w > maxW) {
          fontSize--;
          p.textSize(fontSize);
          w = p.textWidth(currentText);
      }

      if (w > maxW) {
          while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) {
              currentText = currentText.slice(0, -1);
          }
          currentText += '..';
      }

      p.text(currentText, x, y);
  }

  // --- Sub-Renderers ---

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, h * 0.3);
      p.vertex(w, 0);
      p.vertex(w, h);
      p.vertex(0, h * 0.7);
      p.endShape(p.CLOSE);

      p.fill('#64748b'); p.noStroke();
      p.circle(0, h/2, 5); 
      const step = h/3;
      p.circle(w, step, 4); 
      p.circle(w, step*2, 4); 

      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("/", w/2, h/2);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, 0);
      p.vertex(w, h * 0.3);
      p.vertex(w, h * 0.7);
      p.vertex(0, h);
      p.endShape(p.CLOSE);

      p.fill('#64748b'); p.noStroke();
      const step = h/3;
      p.circle(0, step, 4); 
      p.circle(0, step*2, 4);
      p.circle(w, h/2, 5);

      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("&", w/2, h/2);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.fill('#eff6ff'); 
    p.stroke('#3b82f6'); 
    p.strokeWeight(2);
    p.rect(0, 0, w, h, 6);

    p.fill('#1e3a8a'); 
    p.noStroke(); 
    p.textStyle(p.BOLD);

    const label = comp.customLabel || "IC";
    CircuitRenderer.drawFittedText(p, label, w/2, h/2, w - 4, h - 4);

    if (comp.functionId) {
        const funcDef = library.find(f => f.id === comp.functionId);
        if (funcDef) {
            const inputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true);
            const outputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

            const drawPort = (c: CircuitComponent, index: number, isInput: boolean) => {
                const pt = CircuitRenderer.getPortPosition(comp, index, isInput ? 'input' : 'output', library);
                const rx = pt.x - comp.x;
                const ry = pt.y - comp.y;

                p.fill(isInput ? '#3b82f6' : '#f59e0b');
                p.stroke('#1e293b'); p.strokeWeight(1);
                p.circle(rx, ry, 6);

                if (c.customLabel) {
                    p.noStroke();
                    p.fill('#334155');
                    p.textSize(8);
                    p.textStyle(p.NORMAL);

                    if (pt.side === 'left') {
                        p.textAlign(p.LEFT, p.CENTER);
                        p.text(c.customLabel, rx + 6, ry);
                    } else if (pt.side === 'right') {
                        p.textAlign(p.RIGHT, p.CENTER);
                        p.text(c.customLabel, rx - 6, ry);
                    } else if (pt.side === 'top') {
                         p.textAlign(p.CENTER, p.TOP);
                         p.text(c.customLabel, rx, ry + 6);
                    } else { 
                         p.textAlign(p.CENTER, p.BOTTOM);
                         p.text(c.customLabel, rx, ry - 6);
                    }
                }
            };

            inputs.forEach((c, i) => drawPort(c, i, true));
            outputs.forEach((c, i) => drawPort(c, i, false));
        }
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      const side = comp.icPortSide || 'right';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = w, portY = h/2;
      if (side === 'left') { portX = 0; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.fill(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_BG);
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');

      if (comp.bitWidth >= 16) {
          p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
          p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
          const hex = "0x" + bitsToHex(comp.outputValues[0] || []);
          CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      } else {
          p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
          p.text(isOn ? "1" : "0", w/2, h/2);
      }
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      const side = comp.icPortSide || 'left';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = 0, portY = h/2;
      if (side === 'right') { portX = w; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      if (isOn) { p.noStroke(); p.fill(245, 158, 11, 80); p.rect(boxOffset-3, boxOffset-3, boxSize+6, boxSize+6, 6); }
      p.stroke(isOn ? COLOR_BUS_ON : '#334155');
      p.fill(isOn ? COLOR_BUS_ON : '#1e293b');
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');
      if (comp.bitWidth >= 16) {
           p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
           p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
           const hex = "0x" + bitsToHex(comp.inputValues[0] || []);
           CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      }
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const padX = 4;
      p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, 4, w - (padX*2), h-8, 4);
      p.noStroke(); p.fill('#ef4444'); 

      const hex = bitsToHex(comp.inputValues[0] || []);

      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - (padX*2) - 4, h - 12);

      p.fill('#64748b'); p.circle(0, h/2, 5);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    const py = 6;
    const gateW = w - 10;
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = isNegated ? gateW - (bubbleR*2) : gateW;

    p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
    p.line(gateW, h/2, w, h/2); 

    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
    } else {
        const isXor = comp.type === 'XOR';
        const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);
        let startX = 0;

        if (isXor) {
            startX = 5;
            p.noFill();
            p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py); p.endShape();
        }

        p.fill(COLOR_COMPONENT_BG);
        p.beginShape();
        if (isOrFamily) {
            p.vertex(startX, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(startX, h - py);
            (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);
        } else {
            p.vertex(0, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(0, h - py); p.vertex(0, py);
        }
        p.endShape(p.CLOSE);
    }

    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); p.circle(gateW - bubbleR, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke(); p.fill('#1e293b'); p.textSize(12); p.textStyle(p.BOLD);
        p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        p.textStyle(p.NORMAL);
      }
  }
}

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
  focusComponent: (compId: string) => void;
  // Clipboard & Selection Actions
  copy: () => void;
  paste: () => void;
  selectAll: () => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'PAN' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

interface SelectionBox {
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  active: boolean;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // State Refs
  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  // Selection State
  const selectedCompIds = useRef<Set<string>>(new Set()); // Multi-selection
  const selectionBoxRef = useRef<SelectionBox>({ startX: 0, startY: 0, currentX: 0, currentY: 0, active: false });
  const clipboardRef = useRef<{ components: CircuitComponent[], wires: Wire[] } | null>(null);

  // Interaction State
  const activeDragIds = useRef<Set<string>>(new Set()); // IDs being dragged
  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragStartPos = useRef<Point>({ x: 0, y: 0 }); // World position where drag started
  const accumTimeRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  // -- Clipboard Logic --
  const handleCopy = () => {
      if (selectedCompIds.current.size === 0) return;
      const selectedComps = componentsRef.current.filter(c => selectedCompIds.current.has(c.id));
      const internalWires = wiresRef.current.filter(w => 
          selectedCompIds.current.has(w.fromCompId) && selectedCompIds.current.has(w.toCompId)
      );

      clipboardRef.current = {
          components: JSON.parse(JSON.stringify(selectedComps)),
          wires: JSON.parse(JSON.stringify(internalWires))
      };
      console.log(`Copied ${selectedComps.length} items to clipboard`);
  };

  const handlePaste = () => {
      if (!clipboardRef.current) return;
      const { components: clipComps, wires: clipWires } = clipboardRef.current;

      clearSelection();

      const idMap = new Map<string, string>();
      const OFFSET = GRID_SIZE; 

      const newComps: CircuitComponent[] = clipComps.map(c => {
          const newId = crypto.randomUUID();
          idMap.set(c.id, newId);
          return {
              ...c,
              id: newId,
              x: c.x + OFFSET,
              y: c.y + OFFSET,
              inputValues: c.inputValues.map(v => []),
              outputValues: c.outputValues.map(v => []) 
          };
      });

      const newWires: Wire[] = clipWires.map(w => ({
          ...w,
          id: crypto.randomUUID(),
          fromCompId: idMap.get(w.fromCompId)!,
          toCompId: idMap.get(w.toCompId)!,
          state: new Array(w.bitWidth).fill(false)
      }));

      componentsRef.current.push(...newComps);
      wiresRef.current.push(...newWires);

      newComps.forEach(c => selectedCompIds.current.add(c.id));
      if (newComps.length > 0 && onSelectionChange) {
          onSelectionChange(newComps[newComps.length - 1]);
      }
  };

  const handleSelectAll = () => {
      componentsRef.current.forEach(c => selectedCompIds.current.add(c.id));
      if (onSelectionChange && componentsRef.current.length > 0) {
          onSelectionChange(componentsRef.current[componentsRef.current.length - 1]);
      }
  };

  const handleDelete = () => {
     if (selectedCompIds.current.size === 0) return;
     const idsToDelete = selectedCompIds.current;
     componentsRef.current = componentsRef.current.filter(c => !idsToDelete.has(c.id));
     wiresRef.current = wiresRef.current.filter(w => !idsToDelete.has(w.fromCompId) && !idsToDelete.has(w.toCompId));
     clearSelection();
  };

  // -- Exposed Methods --
  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        let updatedCount = 0;
        componentsRef.current.forEach(c => {
            if (selectedCompIds.current.has(c.id)) {
                Object.assign(c, updates);
                updatedCount++;
            }
        });
        if (updatedCount > 0 && onSelectionChange) {
             const lastId = Array.from(selectedCompIds.current).pop();
             const comp = componentsRef.current.find(c => c.id === lastId) || null;
             onSelectionChange(comp); 
        }
    },
    deleteSelected: handleDelete,
    setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) {
                while(currentBus.length < comp.bitWidth) currentBus.push(false);
            }
            const newBus = [...currentBus];
            newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    },
    focusComponent: (compId: string) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && containerRef.current) {
             const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
             const w = dims.w * GRID_SIZE;
             const h = dims.h * GRID_SIZE;
             const cx = comp.x + w/2;
             const cy = comp.y + h/2;
             const sw = containerRef.current.clientWidth;
             const sh = containerRef.current.clientHeight;

             viewportRef.current.x = (sw/2) - (cx * viewportRef.current.zoom);
             viewportRef.current.y = (sh/2) - (cy * viewportRef.current.zoom);
        }
    },
    copy: handleCopy,
    paste: handlePaste,
    selectAll: handleSelectAll
  }));

  // -- Logic Helpers --

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  const clearSelection = () => {
    selectedCompIds.current.clear();
    if (onSelectionChange) onSelectionChange(null);
  };

  const addToSelection = (id: string) => {
    selectedCompIds.current.add(id);
    const comp = componentsRef.current.find(c => c.id === id) || null;
    if (onSelectionChange) onSelectionChange(comp);
  };

  const toggleSelection = (id: string) => {
    if (selectedCompIds.current.has(id)) {
        selectedCompIds.current.delete(id);
        if (onSelectionChange) onSelectionChange(null); 
    } else {
        selectedCompIds.current.add(id);
        const comp = componentsRef.current.find(c => c.id === id) || null;
        if (onSelectionChange) onSelectionChange(comp);
    }
  };

  // Keyboard Shortcuts
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement) return;

          const key = e.key.toLowerCase();
          const ctrl = e.ctrlKey || e.metaKey;

          if (key === 'delete' || key === 'backspace') {
              handleDelete();
          } else if (ctrl && key === 'c') {
              handleCopy();
          } else if (ctrl && key === 'v') {
              handlePaste();
          } else if (ctrl && key === 'a') {
              e.preventDefault();
              handleSelectAll();
          }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs;
    outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    }

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill([]), 
      outputValues: new Array(outputsCount).fill([]), 
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined,
      bitWidth: bitWidth
    };

    componentsRef.current.push(newComp);
    clearSelection();
    addToSelection(newComp.id);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      if (comp.type === ComponentType.SPLITTER) {
          if (type === 'input') return comp.bitWidth; 
          return comp.bitWidth / 2;
      }
      if (comp.type === ComponentType.MERGER) {
          if (type === 'output') return comp.bitWidth;
          return comp.bitWidth / 2; 
      }
      return comp.bitWidth;
  };

  // --- P5.js Sketch ---
  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;
      let isRightMousePressed = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);

        // Simulation Loop
        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
              }
              accumTimeRef.current = 0;
          } else {
              accumTimeRef.current += p.deltaTime;
              if (accumTimeRef.current > 500) accumTimeRef.current = 500; 
              while (accumTimeRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
                accumTimeRef.current -= speed;
              }
          }
        } else accumTimeRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        // 1. Grid & Wires
        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        // 2. Wiring Draft
        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        // 3. Components
        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, selectedCompIds.current.has(comp.id));
        });

        // 4. Selection Box
        if (selectionBoxRef.current.active) {
            CircuitRenderer.drawSelectionRect(p, 
                selectionBoxRef.current.startX, 
                selectionBoxRef.current.startY, 
                selectionBoxRef.current.currentX - selectionBoxRef.current.startX, 
                selectionBoxRef.current.currentY - selectionBoxRef.current.startY
            );
        }

        // 5. Hover Highlights
        if (!isDraggingComp.current && !selectionBoxRef.current.active) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);

            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; 
                        else if (wiringStart.current.type === hPort.type) isValid = false; 
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false;
                    }
                    p.noFill();
                    p.stroke(isValid ? '#3b82f6' : '#ef4444'); 
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);
                }
            }
        }

        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (let i = componentsRef.current.length - 1; i >= 0; i--) {
          const comp = componentsRef.current[i];
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- Interaction Handling --

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;

        isRightMousePressed = (p.mouseButton === p.RIGHT) || p.keyIsDown(p.CONTROL); 
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // 1. Pan Mode
        // If PAN tool is active, or user Right Clicks / Spacebar
        if (toolRef.current === 'PAN' || isRightMousePressed || p.keyIsDown(32)) { 
             isPanningRef.current = true;
             return;
        }

        // 2. Wiring (Only if not in PAN mode)
        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
            wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
            return;
        }

        // 3. Component Select / Drag
        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
            if (toolRef.current === 'DELETE') {
                 selectedCompIds.current.clear();
                 selectedCompIds.current.add(compId);
                 handleDelete();
                 return;
            }

            if (p.keyIsDown(p.SHIFT)) {
                toggleSelection(compId);
            } else if (!selectedCompIds.current.has(compId)) {
                clearSelection();
                addToSelection(compId);
            }

            if (selectedCompIds.current.has(compId)) {
                 isDraggingComp.current = true;
                 dragStartPos.current = { x: mouseWorld.x, y: mouseWorld.y };
                 activeDragIds.current = new Set(selectedCompIds.current);
            }
            return;
        }

        // 4. Area Selection (Only in SELECT mode, if clicked on background)
        if (!wiringStart.current && toolRef.current === 'SELECT') {
            clearSelection();
            selectionBoxRef.current = {
                startX: mouseWorld.x,
                startY: mouseWorld.y,
                currentX: mouseWorld.x,
                currentY: mouseWorld.y,
                active: true
            };
        }
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return; // Touch handled separately
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
        } else if (isDraggingComp.current && activeDragIds.current.size > 0) {
           componentsRef.current.forEach(c => {
               if (activeDragIds.current.has(c.id)) {
                   c.x += (p.mouseX - p.pmouseX) / viewportRef.current.zoom;
                   c.y += (p.mouseY - p.pmouseY) / viewportRef.current.zoom;
               }
           });
           dragStartPos.current = mouseWorld;
        } else if (selectionBoxRef.current.active) {
            selectionBoxRef.current.currentX = mouseWorld.x;
            selectionBoxRef.current.currentY = mouseWorld.y;
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        if (isDraggingComp.current) {
            componentsRef.current.forEach(c => {
                if (activeDragIds.current.has(c.id)) {
                    c.x = Math.round(c.x / GRID_SIZE) * GRID_SIZE;
                    c.y = Math.round(c.y / GRID_SIZE) * GRID_SIZE;
                }
            });
        }

        if (!isPanningRef.current && !selectionBoxRef.current.active && !wiringStart.current) {
             const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
             if (compId && !isDraggingComp.current) {
                  // Click interaction
                  const comp = componentsRef.current.find(c => c.id === compId);
                  if (comp && comp.type === ComponentType.INPUT_SWITCH && comp.bitWidth === 1) {
                        const val = comp.outputValues[0]?.[0] || false;
                        comp.outputValues[0] = new Array(comp.bitWidth).fill(!val);
                  }
             }
        }

        if (selectionBoxRef.current.active) {
            const bx = Math.min(selectionBoxRef.current.startX, selectionBoxRef.current.currentX);
            const by = Math.min(selectionBoxRef.current.startY, selectionBoxRef.current.currentY);
            const bw = Math.abs(selectionBoxRef.current.currentX - selectionBoxRef.current.startX);
            const bh = Math.abs(selectionBoxRef.current.currentY - selectionBoxRef.current.startY);

            if (bw > 2 || bh > 2) {
                componentsRef.current.forEach(c => {
                    const dims = CircuitRenderer.getComponentDimensions(c, libraryRef.current);
                    const cw = dims.w * GRID_SIZE;
                    const ch = dims.h * GRID_SIZE;
                    if (c.x < bx + bw && c.x + cw > bx && c.y < by + bh && c.y + ch > by) {
                        selectedCompIds.current.add(c.id);
                    }
                });
                if (selectedCompIds.current.size > 0 && onSelectionChange) {
                     const ids = Array.from(selectedCompIds.current);
                     const last = componentsRef.current.find(c => c.id === ids[ids.length-1]) || null;
                     onSelectionChange(last);
                }
            }
        }

        activeDragIds.current.clear();
        isDraggingComp.current = false;
        isPanningRef.current = false;
        selectionBoxRef.current.active = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;

             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

                if (src.type === 'output' && dst.type === 'input') {
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(),
                      fromCompId: src.compId,
                      fromPortIndex: src.portIndex,
                      toCompId: dst.compId,
                      toPortIndex: dst.portIndex,
                      state: new Array(wiringStart.current.bitWidth).fill(false),
                      bitWidth: wiringStart.current.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };

      // --- Touch Support ---
      (p as any).touchStarted = (e: any) => { 
        if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } 
        isCanvasInteraction = true; 

        if (p.touches.length === 2) { 
             // 2-finger Pan/Zoom always works
             const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
             pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); 
        } else if (p.touches.length === 1) { 
             lastTouchX = (p.touches[0] as any).x; 
             lastTouchY = (p.touches[0] as any).y; 
             // Trigger mousePressed logic to select/drag items
             p.mousePressed(undefined); 
        } 
        return false; 
      };

      (p as any).touchMoved = (e: any) => { 
        if (!isCanvasInteraction) return true; 

        if (p.touches.length === 2) { 
            // 2-finger Zoom
            const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
            const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); 
            if (pinchDistStart > 0) { 
                const scaleFactor = currentDist / pinchDistStart; 
                const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); 
                const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; 
                const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; 
                const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; 
                viewportRef.current.x = cx - wx * newZoom; 
                viewportRef.current.y = cy - wy * newZoom; 
                viewportRef.current.zoom = newZoom; 
                pinchDistStart = currentDist; 
            } 
        } else if (p.touches.length === 1) { 
            // 1-finger Action
            // If Tool is PAN, prioritize Panning
            if (toolRef.current === 'PAN') {
                viewportRef.current.x += ((p.touches[0] as any).x - lastTouchX);
                viewportRef.current.y += ((p.touches[0] as any).y - lastTouchY);
                isPanningRef.current = true;
            } else {
                // If dragging a component or wiring, use standard logic
                if (isDraggingComp.current || wiringStart.current) {
                    p.mouseDragged();
                } else {
                    // If SELECT tool and background drag, do Box Select
                    // Note: p.mouseDragged handles Box Select if selectionBoxRef.active is true (set in mousePressed)
                    if (selectionBoxRef.current.active) {
                        p.mouseDragged();
                    } else {
                        // Fallback: If not box selecting and not dragging comp, maybe pan?
                        // In SELECT mode, we usually want Box Select. 
                        // But on Mobile, Pan is useful. 
                        // Design decision: PAN tool handles Pan. SELECT tool handles selection.
                        // So here we assume user wants to select if tool is SELECT.
                        p.mouseDragged();
                    }
                }
            }
            lastTouchX = (p.touches[0] as any).x; 
            lastTouchY = (p.touches[0] as any).y; 
        } 
        return false; 
      };

      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        if (e.target !== (p as any).canvas) return true;
        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
      tabIndex={0} 
    />
  );
});

export default LogicCanvas;

import React, { useState } from 'react';
import { ComponentType, FunctionCircuit } from '../types';
import { COMPONENT_DEFINITIONS, VALID_BIT_WIDTHS } from '../constants';
import DraggableItem from './DraggableItem';

interface SidebarProps {
  selectedTool: 'SELECT' | 'PAN' | 'DELETE';
  onSelectTool: (t: 'SELECT' | 'PAN' | 'DELETE') => void;
  selectedBitWidth: number;
  onSelectBitWidth: (w: number) => void;
  onTouchStartItem?: (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => void;
  functionLibrary: FunctionCircuit[];
  // Clipboard actions
  onCopy: () => void;
  onPaste: () => void;
  onSelectAll: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
    selectedTool, 
    onSelectTool, 
    selectedBitWidth, 
    onSelectBitWidth,
    onTouchStartItem, 
    functionLibrary,
    onCopy,
    onPaste,
    onSelectAll
}) => {
  const [searchTerm, setSearchTerm] = useState("");

  const groups = [
    { name: 'Bus Tools', items: [ComponentType.SPLITTER, ComponentType.MERGER] },
    { name: 'I/O', items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.HEX_DISPLAY] },
    { name: 'Gates', items: [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR] }
  ];

  // Search Logic
  const filteredGroups = groups.map(group => ({
    ...group,
    items: group.items.filter(type => {
        if (!searchTerm) return true;
        const def = COMPONENT_DEFINITIONS[type];
        const lowerTerm = searchTerm.toLowerCase();
        return def.label.toLowerCase().includes(lowerTerm) || 
               def.description.toLowerCase().includes(lowerTerm) ||
               type.toLowerCase().includes(lowerTerm);
    })
  })).filter(g => g.items.length > 0);

  const filteredFunctions = functionLibrary.filter(f => 
      f.id !== 'main' && 
      (searchTerm ? f.name.toLowerCase().includes(searchTerm.toLowerCase()) : true)
  );

  return (
    <div className="w-64 bg-white border-r border-slate-200 flex flex-col h-full shadow-lg z-10">
      <div className="p-4 border-b border-slate-100 bg-slate-50/50">
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">LogicFlow</h1>
        <p className="text-xs text-slate-400 mt-1">Bus Width Simulator</p>
      </div>

      <div className="p-3 border-b border-slate-50">
        <div className="relative">
            <span className="absolute left-2.5 top-1.5 text-slate-400 text-sm">🔍</span>
            <input 
                type="text"
                placeholder="Search components..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-8 pr-3 py-1.5 text-sm bg-slate-100 border-transparent focus:bg-white border focus:border-blue-300 rounded-md outline-none transition-all placeholder-slate-400 text-slate-700"
            />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 overscroll-contain scrollbar-thin">

        {/* Tools Section */}
        <section>
          <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">Tools</h3>
          <div className="grid grid-cols-3 gap-2 mb-3">
            <button
              onClick={() => onSelectTool('SELECT')}
              className={`p-2 rounded text-xs font-bold transition-colors flex flex-col items-center justify-center gap-1 ${selectedTool === 'SELECT' ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title="Select / Move"
            >
              <span className="text-base">👆</span> Sel
            </button>
            <button
              onClick={() => onSelectTool('PAN')}
              className={`p-2 rounded text-xs font-bold transition-colors flex flex-col items-center justify-center gap-1 ${selectedTool === 'PAN' ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title="Pan View"
            >
              <span className="text-base">✋</span> Pan
            </button>
            <button
              onClick={() => onSelectTool('DELETE')}
              className={`p-2 rounded text-xs font-bold transition-colors flex flex-col items-center justify-center gap-1 ${selectedTool === 'DELETE' ? 'bg-red-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title="Delete Item"
            >
              <span className="text-base">🗑️</span> Del
            </button>
          </div>

          {/* Clipboard Actions for Touch Users */}
          <div className="grid grid-cols-3 gap-2">
             <button onClick={onCopy} className="py-1.5 px-2 bg-white border border-slate-200 rounded text-xs font-medium text-slate-600 hover:bg-slate-50 active:scale-95 transition-transform" title="Copy">
                📋 Copy
             </button>
             <button onClick={onPaste} className="py-1.5 px-2 bg-white border border-slate-200 rounded text-xs font-medium text-slate-600 hover:bg-slate-50 active:scale-95 transition-transform" title="Paste">
                📝 Paste
             </button>
             <button onClick={onSelectAll} className="py-1.5 px-2 bg-white border border-slate-200 rounded text-xs font-medium text-slate-600 hover:bg-slate-50 active:scale-95 transition-transform" title="Select All">
                ✅ All
             </button>
          </div>
        </section>

        {/* Bit Width Section */}
        <section>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 pl-1">Bus Width</h3>
            <div className="flex flex-wrap gap-1.5">
                {VALID_BIT_WIDTHS.map(w => (
                    <button
                        key={w}
                        onClick={() => onSelectBitWidth(w)}
                        className={`px-2.5 py-1 text-xs font-bold rounded border transition-all ${selectedBitWidth === w 
                            ? 'bg-blue-100 border-blue-400 text-blue-700 shadow-sm scale-105' 
                            : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                    >
                        {w}
                    </button>
                ))}
            </div>
        </section>

        {/* Component Groups */}
        {filteredGroups.map(group => (
          <section key={group.name}>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">{group.name}</h3>
            <div className="grid grid-cols-2 gap-3">
              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                const disabled = (type === ComponentType.SPLITTER || type === ComponentType.MERGER) && selectedBitWidth < 2;
                const subLabel = type === ComponentType.SPLITTER ? `${selectedBitWidth}→${selectedBitWidth/2}` : 
                                 type === ComponentType.MERGER ? `${selectedBitWidth/2}→${selectedBitWidth}` : 
                                 `x${selectedBitWidth}`;

                return (
                   <DraggableItem 
                        key={type}
                        type={type}
                        label={def.label}
                        subLabel={subLabel}
                        disabled={disabled}
                        bitWidth={selectedBitWidth}
                        onTouchStartItem={onTouchStartItem}
                   />
                );
              })}
            </div>
          </section>
        ))}

        {/* Custom Functions Section */}
        {(filteredFunctions.length > 0 || (searchTerm && filteredFunctions.length === 0)) && (
            <section>
                 <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">My Functions</h3>
                 {filteredFunctions.length > 0 ? (
                     <div className="grid grid-cols-1 gap-2">
                        {filteredFunctions.map(func => (
                            <DraggableItem
                                key={func.id}
                                type={ComponentType.CUSTOM_IC}
                                label={func.name}
                                subLabel=""
                                disabled={false}
                                bitWidth={selectedBitWidth}
                                functionId={func.id}
                                isCustom={true}
                                onTouchStartItem={onTouchStartItem}
                            />
                        ))}
                     </div>
                 ) : (
                     <p className="text-xs text-slate-400 italic pl-1">No functions match search.</p>
                 )}
            </section>
        )}

      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import Toolbar from './components/Toolbar';
import Modal from './components/Modal';
import { ComponentType, CircuitComponent } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'PAN' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false);
  const [speedSlider, setSpeedSlider] = useState(90); 
  const [selectedBitWidth, setSelectedBitWidth] = useState<number>(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");

  // -- Component Selection --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- Drag & Drop State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string, bitWidth: number} | null>(null);

  // Ref to track drag position without triggering re-renders or stale closures in event handlers
  const dragPosRef = useRef<{x: number, y: number} | null>(null);

  // -- Refs --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Hooks --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // Computed Values
  const tickSpeed = speedSlider === 100 ? 0 : Math.max(1, 500 - (speedSlider * 5));
  const speedLabel = speedSlider === 100 ? "MAX" : `${tickSpeed}ms`;

  // -- Interaction Handlers --

  const handleTouchStartItem = (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => {
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos(pos);
    dragPosRef.current = pos;
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        const newPos = { x: touch.clientX, y: touch.clientY };
        setDragPos(newPos);
        dragPosRef.current = newPos;
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      const finalPos = dragPosRef.current;
      if (draggedType && finalPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          finalPos.x >= rect.left && finalPos.x <= rect.right &&
          finalPos.y >= rect.top && finalPos.y <= rect.bottom
        ) {
          setPendingDrop({ 
            type: draggedType, 
            x: finalPos.x - rect.left, 
            y: finalPos.y - rect.top, 
            functionId: draggedFuncId, 
            bitWidth: selectedBitWidth 
          });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
      dragPosRef.current = null;
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, draggedFuncId, selectedBitWidth]);

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      setTempLabel(comp?.customLabel || "");
  };

  // Poll for Simulation Updates (Live Monitor)
  const selectedIdRef = useRef<string | null>(null);
  useEffect(() => { selectedIdRef.current = selectedComponent?.id || null; }, [selectedComponent]);

  useEffect(() => {
      if (!isPlaying) return;
      const interval = setInterval(() => {
          const currentId = selectedIdRef.current;
          if (!currentId || !canvasRef.current) return;

          const { components } = canvasRef.current.getData();
          const freshComp = components.find(c => c.id === currentId);

          if (freshComp) {
              setSelectedComponent(prev => {
                  if (!prev || prev.id !== currentId) return prev;
                  // Optimization: Only update React state if logic state changed
                  const prevHash = JSON.stringify({ i: prev.inputValues, o: prev.outputValues });
                  const newHash = JSON.stringify({ i: freshComp.inputValues, o: freshComp.outputValues });
                  return prevHash !== newHash ? { ...freshComp } : prev;
              });
          }
      }, 100);
      return () => clearInterval(interval);
  }, [isPlaying]); 

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        selectedBitWidth={selectedBitWidth}
        onSelectBitWidth={setSelectedBitWidth}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
        onCopy={() => canvasRef.current?.copy()}
        onPaste={() => canvasRef.current?.paste()}
        onSelectAll={() => canvasRef.current?.selectAll()}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">

        <Toolbar 
            activeFunctionId={activeFunctionId}
            functions={functions}
            isPlaying={isPlaying}
            speedSlider={speedSlider}
            speedLabel={speedLabel}
            selectedComponent={selectedComponent}
            tempLabel={tempLabel}
            lastSaved={lastSaved}
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onSpeedChange={setSpeedSlider}
            onFunctionChange={(id) => { setIsPlaying(false); switchToFunction(id); }}
            onAddFunction={() => setIsModalOpen(true)}
            onDeleteFunction={deleteFunction}
            onFocusComponent={() => selectedComponent && canvasRef.current?.focusComponent(selectedComponent.id)}
            onUpdateComponent={updateProp}
            onBitToggle={(idx) => {
                if (selectedComponent && canvasRef.current) {
                    const currentBus = selectedComponent.outputValues[0] || new Array(selectedComponent.bitWidth).fill(false);
                    canvasRef.current.setComponentOutputBit(selectedComponent.id, idx, !currentBus[idx]);
                    // Optimistic update
                    const newBus = [...currentBus]; newBus[idx] = !newBus[idx];
                    setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
                }
            }}
            onBatchBusChange={(newBus) => {
                if (selectedComponent && canvasRef.current) {
                    canvasRef.current.updateSelectedComponent({ outputValues: [newBus] });
                    setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
                }
            }}
            onLabelChange={(val) => { setTempLabel(val); updateProp({ customLabel: val }); }}
            onSave={persist}
            onImport={() => fileInputRef.current?.click()}
            onExportProject={() => handleExport('PROJECT')}
            onExportFunction={() => handleExport('FUNCTION')}
            onClear={() => { if(confirm("Clear all data?")) clearData(); }}
        />

        {/* Main Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost Visual */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-90" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-white border-2 border-blue-500 rounded-lg flex items-center justify-center shadow-2xl">
              <span className="text-[10px] font-bold text-slate-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label.substring(0,3)}</span>
              <span className="absolute -top-2 -right-2 bg-blue-600 text-white text-[9px] w-5 h-5 flex items-center justify-center rounded-full shadow-sm">{selectedBitWidth}</span>
            </div>
          </div>
        )}

        <Modal 
            isOpen={isModalOpen}
            title="Create New Function"
            onClose={() => setIsModalOpen(false)}
            onSubmit={() => {
                if (newFuncName.trim()) {
                    addFunction(newFuncName);
                    setNewFuncName("");
                    setIsModalOpen(false);
                }
            }}
        >
             <input 
                autoFocus 
                type="text" 
                value={newFuncName} 
                onChange={(e) => setNewFuncName(e.target.value)} 
                placeholder="Function Name (e.g., Full Adder)" 
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-blue-400 outline-none transition-all" 
            />
        </Modal>

      </main>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
  focusComponent: (compId: string) => void;
  copy: () => void;
  paste: () => void;
  selectAll: () => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'PAN' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

interface SelectionBox {
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  active: boolean;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // State Refs
  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  const selectedCompIds = useRef<Set<string>>(new Set()); 
  const selectionBoxRef = useRef<SelectionBox>({ startX: 0, startY: 0, currentX: 0, currentY: 0, active: false });
  const clipboardRef = useRef<{ components: CircuitComponent[], wires: Wire[] } | null>(null);

  // Interaction State
  const activeDragIds = useRef<Set<string>>(new Set());
  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const hasDraggedRef = useRef<boolean>(false); // To distinguish click vs drag
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragStartPos = useRef<Point>({ x: 0, y: 0 }); 
  const accumTimeRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  // -- Clipboard Logic --
  const handleCopy = () => {
      if (selectedCompIds.current.size === 0) return;
      const selectedComps = componentsRef.current.filter(c => selectedCompIds.current.has(c.id));
      const internalWires = wiresRef.current.filter(w => 
          selectedCompIds.current.has(w.fromCompId) && selectedCompIds.current.has(w.toCompId)
      );

      clipboardRef.current = {
          components: JSON.parse(JSON.stringify(selectedComps)),
          wires: JSON.parse(JSON.stringify(internalWires))
      };
      console.log(`Copied ${selectedComps.length} items to clipboard`);
  };

  const handlePaste = () => {
      if (!clipboardRef.current) return;
      const { components: clipComps, wires: clipWires } = clipboardRef.current;
      clearSelection();
      const idMap = new Map<string, string>();
      const OFFSET = GRID_SIZE; 
      const newComps: CircuitComponent[] = clipComps.map(c => {
          const newId = crypto.randomUUID();
          idMap.set(c.id, newId);
          return { ...c, id: newId, x: c.x + OFFSET, y: c.y + OFFSET, inputValues: c.inputValues.map(v => []), outputValues: c.outputValues.map(v => []) };
      });
      const newWires: Wire[] = clipWires.map(w => ({
          ...w, id: crypto.randomUUID(), fromCompId: idMap.get(w.fromCompId)!, toCompId: idMap.get(w.toCompId)!, state: new Array(w.bitWidth).fill(false)
      }));
      componentsRef.current.push(...newComps);
      wiresRef.current.push(...newWires);
      newComps.forEach(c => selectedCompIds.current.add(c.id));
      if (newComps.length > 0 && onSelectionChange) onSelectionChange(newComps[newComps.length - 1]);
  };

  const handleSelectAll = () => {
      componentsRef.current.forEach(c => selectedCompIds.current.add(c.id));
      if (onSelectionChange && componentsRef.current.length > 0) onSelectionChange(componentsRef.current[componentsRef.current.length - 1]);
  };

  const handleDelete = () => {
     if (selectedCompIds.current.size === 0) return;
     const idsToDelete = selectedCompIds.current;
     componentsRef.current = componentsRef.current.filter(c => !idsToDelete.has(c.id));
     wiresRef.current = wiresRef.current.filter(w => !idsToDelete.has(w.fromCompId) && !idsToDelete.has(w.toCompId));
     clearSelection();
  };

  useImperativeHandle(ref, () => ({
    getData: () => ({ components: componentsRef.current, wires: wiresRef.current }),
    updateSelectedComponent: (updates) => {
        let updatedCount = 0;
        componentsRef.current.forEach(c => {
            if (selectedCompIds.current.has(c.id)) { Object.assign(c, updates); updatedCount++; }
        });
        if (updatedCount > 0 && onSelectionChange) {
             const lastId = Array.from(selectedCompIds.current).pop();
             const comp = componentsRef.current.find(c => c.id === lastId) || null;
             onSelectionChange(comp); 
        }
    },
    deleteSelected: handleDelete,
    setComponentOutputBit: (compId, bitIndex, value) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) while(currentBus.length < comp.bitWidth) currentBus.push(false);
            const newBus = [...currentBus]; newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    },
    focusComponent: (compId) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && containerRef.current) {
             const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
             const cx = comp.x + (dims.w * GRID_SIZE)/2;
             const cy = comp.y + (dims.h * GRID_SIZE)/2;
             const sw = containerRef.current.clientWidth;
             const sh = containerRef.current.clientHeight;
             viewportRef.current.x = (sw/2) - (cx * viewportRef.current.zoom);
             viewportRef.current.y = (sh/2) - (cy * viewportRef.current.zoom);
        }
    },
    copy: handleCopy, paste: handlePaste, selectAll: handleSelectAll
  }));

  const screenToWorld = (sx: number, sy: number): Point => ({
    x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
    y: (sy - viewportRef.current.y) / viewportRef.current.zoom
  });

  const clearSelection = () => { selectedCompIds.current.clear(); if (onSelectionChange) onSelectionChange(null); };
  const addToSelection = (id: string) => { selectedCompIds.current.add(id); const comp = componentsRef.current.find(c => c.id === id) || null; if (onSelectionChange) onSelectionChange(comp); };
  const toggleSelection = (id: string) => {
    if (selectedCompIds.current.has(id)) { selectedCompIds.current.delete(id); if (onSelectionChange) onSelectionChange(null); } 
    else { selectedCompIds.current.add(id); const comp = componentsRef.current.find(c => c.id === id) || null; if (onSelectionChange) onSelectionChange(comp); }
  };

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement) return;
          const key = e.key.toLowerCase(); const ctrl = e.ctrlKey || e.metaKey;
          if (key === 'delete' || key === 'backspace') handleDelete();
          else if (ctrl && key === 'c') handleCopy();
          else if (ctrl && key === 'v') handlePaste();
          else if (ctrl && key === 'a') { e.preventDefault(); handleSelectAll(); }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;
    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs; outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = { components: JSON.parse(JSON.stringify(func.components)), wires: JSON.parse(JSON.stringify(func.wires)) };
        }
    }
    const newComp: CircuitComponent = {
      id: crypto.randomUUID(), type: type, x: snapX, y: snapY,
      inputValues: new Array(inputsCount).fill([]), outputValues: new Array(outputsCount).fill([]),
      functionId: functionId, internalState: internalState, customLabel: type === ComponentType.CUSTOM_IC ? label : undefined, bitWidth: bitWidth
    };
    componentsRef.current.push(newComp);
    clearSelection(); addToSelection(newComp.id);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      if (comp.type === ComponentType.SPLITTER) return type === 'input' ? comp.bitWidth : comp.bitWidth / 2;
      if (comp.type === ComponentType.MERGER) return type === 'output' ? comp.bitWidth : comp.bitWidth / 2; 
      return comp.bitWidth;
  };

  // --- P5.js Sketch ---
  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;
      let isRightMousePressed = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);
        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components; wiresRef.current = result.wires;
              }
              accumTimeRef.current = 0;
          } else {
              accumTimeRef.current += p.deltaTime;
              if (accumTimeRef.current > 500) accumTimeRef.current = 500; 
              while (accumTimeRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components; wiresRef.current = result.wires;
                accumTimeRef.current -= speed;
              }
          }
        } else accumTimeRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, selectedCompIds.current.has(comp.id));
        });

        if (selectionBoxRef.current.active) {
            CircuitRenderer.drawSelectionRect(p, 
                selectionBoxRef.current.startX, 
                selectionBoxRef.current.startY, 
                selectionBoxRef.current.currentX - selectionBoxRef.current.startX, 
                selectionBoxRef.current.currentY - selectionBoxRef.current.startY
            );
        }

        if (!isDraggingComp.current && !selectionBoxRef.current.active) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; 
                        else if (wiringStart.current.type === hPort.type) isValid = false; 
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false;
                    }
                    p.noFill(); p.stroke(isValid ? '#3b82f6' : '#ef4444'); p.strokeWeight(2); p.circle(pos.x, pos.y, 14);
                }
            }
        }
        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (let i = componentsRef.current.length - 1; i >= 0; i--) {
          const comp = componentsRef.current[i];
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // --- Unified Interaction Logic ---

      // Shared logic for Mouse and Touch dragging
      const handleDragMove = (dx: number, dy: number, currentX: number, currentY: number) => {
          if (Math.abs(dx) > 0 || Math.abs(dy) > 0) hasDraggedRef.current = true;

          const mouseWorld = screenToWorld(currentX, currentY);

          if (isPanningRef.current) {
              viewportRef.current.x += dx;
              viewportRef.current.y += dy;
          } else if (isDraggingComp.current && activeDragIds.current.size > 0) {
              componentsRef.current.forEach(c => {
                  if (activeDragIds.current.has(c.id)) {
                      c.x += dx / viewportRef.current.zoom;
                      c.y += dy / viewportRef.current.zoom;
                  }
              });
              dragStartPos.current = mouseWorld;
          } else if (selectionBoxRef.current.active) {
              selectionBoxRef.current.currentX = mouseWorld.x;
              selectionBoxRef.current.currentY = mouseWorld.y;
          }
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;

        // Reset drag flag
        hasDraggedRef.current = false;

        isRightMousePressed = (p.mouseButton === p.RIGHT) || p.keyIsDown(p.CONTROL); 
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        if (toolRef.current === 'PAN' || isRightMousePressed || p.keyIsDown(32)) { 
             isPanningRef.current = true;
             return;
        }

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
            wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
            return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
            if (toolRef.current === 'DELETE') {
                 selectedCompIds.current.clear();
                 selectedCompIds.current.add(compId);
                 handleDelete();
                 return;
            }

            if (p.keyIsDown(p.SHIFT)) {
                toggleSelection(compId);
            } else if (!selectedCompIds.current.has(compId)) {
                clearSelection();
                addToSelection(compId);
            }

            if (selectedCompIds.current.has(compId)) {
                 isDraggingComp.current = true;
                 dragStartPos.current = { x: mouseWorld.x, y: mouseWorld.y };
                 activeDragIds.current = new Set(selectedCompIds.current);
            }
            return;
        }

        // Area Selection: Trigger if clicking background in SELECT mode
        if (!wiringStart.current && toolRef.current === 'SELECT') {
            clearSelection();
            selectionBoxRef.current = {
                startX: mouseWorld.x, startY: mouseWorld.y,
                currentX: mouseWorld.x, currentY: mouseWorld.y,
                active: true
            };
        }
      };

      p.mouseDragged = () => {
        // We handle logic manually in touchMoved for touch, but for mouse we use p5's mouseDragged.
        // However, if p.touches is active, p5 might still fire mouseDragged depending on browser/device.
        // To avoid double processing or conflicts, we use the standard event but ensure logic is robust.
        // On Desktop, touches is empty. On Mobile, if we handle touchMoved, we might preventDefault.

        if (p.touches.length === 0) {
            handleDragMove(p.mouseX - p.pmouseX, p.mouseY - p.pmouseY, p.mouseX, p.mouseY);
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Snap to Grid
        if (isDraggingComp.current) {
            componentsRef.current.forEach(c => {
                if (activeDragIds.current.has(c.id)) {
                    c.x = Math.round(c.x / GRID_SIZE) * GRID_SIZE;
                    c.y = Math.round(c.y / GRID_SIZE) * GRID_SIZE;
                }
            });
        }

        // Click interaction (Toggle Switch) - Only if NOT panned/dragged significantly
        if (!isPanningRef.current && !selectionBoxRef.current.active && !wiringStart.current) {
             const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
             if (compId && !isDraggingComp.current && !hasDraggedRef.current) {
                  const comp = componentsRef.current.find(c => c.id === compId);
                  if (comp && comp.type === ComponentType.INPUT_SWITCH && comp.bitWidth === 1) {
                        const val = comp.outputValues[0]?.[0] || false;
                        comp.outputValues[0] = new Array(comp.bitWidth).fill(!val);
                  }
             }
        }

        // Finalize Area Selection
        if (selectionBoxRef.current.active) {
            // Normalize Rect
            const bx = Math.min(selectionBoxRef.current.startX, selectionBoxRef.current.currentX);
            const by = Math.min(selectionBoxRef.current.startY, selectionBoxRef.current.currentY);
            const bw = Math.abs(selectionBoxRef.current.currentX - selectionBoxRef.current.startX);
            const bh = Math.abs(selectionBoxRef.current.currentY - selectionBoxRef.current.startY);

            if (bw > 2 || bh > 2) {
                componentsRef.current.forEach(c => {
                    const dims = CircuitRenderer.getComponentDimensions(c, libraryRef.current);
                    const cw = dims.w * GRID_SIZE;
                    const ch = dims.h * GRID_SIZE;
                    // Simple AABB intersection
                    if (c.x < bx + bw && c.x + cw > bx && c.y < by + bh && c.y + ch > by) {
                        selectedCompIds.current.add(c.id);
                    }
                });
                if (selectedCompIds.current.size > 0 && onSelectionChange) {
                     const ids = Array.from(selectedCompIds.current);
                     const last = componentsRef.current.find(c => c.id === ids[ids.length-1]) || null;
                     onSelectionChange(last);
                }
            }
        }

        activeDragIds.current.clear();
        isDraggingComp.current = false;
        isPanningRef.current = false;
        selectionBoxRef.current.active = false;
        hasDraggedRef.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;
             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;
                if (src.type === 'output' && dst.type === 'input') {
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(), fromCompId: src.compId, fromPortIndex: src.portIndex, toCompId: dst.compId, toPortIndex: dst.portIndex,
                      state: new Array(wiringStart.current.bitWidth).fill(false), bitWidth: wiringStart.current.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };

      // --- Touch Support ---
      (p as any).touchStarted = (e: any) => { 
        if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } 
        isCanvasInteraction = true; 

        if (p.touches.length === 2) { 
             const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
             pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); 
        } else if (p.touches.length === 1) { 
             lastTouchX = (p.touches[0] as any).x; 
             lastTouchY = (p.touches[0] as any).y; 
             // Trigger start logic (selection, etc)
             p.mousePressed(undefined); 
        } 
        return false; 
      };

      (p as any).touchMoved = (e: any) => { 
        if (!isCanvasInteraction) return true; 

        if (p.touches.length === 2) { 
            // Zoom
            const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
            const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); 
            if (pinchDistStart > 0) { 
                const scaleFactor = currentDist / pinchDistStart; 
                const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); 
                const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; 
                const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; 
                const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; 
                viewportRef.current.zoom = newZoom; 
                viewportRef.current.x = cx - wx * newZoom; 
                viewportRef.current.y = cy - wy * newZoom; 
                pinchDistStart = currentDist; 
            } 
        } else if (p.touches.length === 1) { 
            const tx = (p.touches[0] as any).x;
            const ty = (p.touches[0] as any).y;
            const dx = tx - lastTouchX;
            const dy = ty - lastTouchY;

            // Unified Drag Logic
            handleDragMove(dx, dy, tx, ty);

            lastTouchX = tx; 
            lastTouchY = ty; 
        } 
        return false; 
      };

      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        if (e.target !== (p as any).canvas) return true;
        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
      tabIndex={0} 
    />
  );
});

export default LogicCanvas;

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

// Helper: Convert boolean array to Hex String using BigInt to support > 31 bits
export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  // --- Sorting Logic for Pins (Must match CircuitEngine) ---
  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          const width = Math.max(1, topCount, bottomCount);
          const height = Math.max(1, leftCount, rightCount);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 1, h: 1, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; 
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);

                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);

                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  // --- Helpers ---

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 2;
      return Math.min(14, 2.5 + Math.ceil(Math.log2(width) * 1.1));
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  // --- Drawing ---

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[]) {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);

        const active = CircuitRenderer.isSignalActive(wire.state);
        const weight = CircuitRenderer.getWireWeight(wire.bitWidth);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(weight);
        p.noFill();

        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);

        if (wire.bitWidth > 1) {
             const midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
             const midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);
             const circleSize = Math.max(12, weight + 4);

             p.noStroke();
             p.fill(COLOR_COMPONENT_BG);
             p.circle(midX, midY, circleSize);

             p.fill(COLOR_COMPONENT_STROKE);
             p.textAlign(p.CENTER, p.CENTER);
             p.textSize(8);
             p.textStyle(p.BOLD);
             p.text(wire.bitWidth, midX, midY);
             p.textStyle(p.NORMAL);
        }
      }
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output', bitWidth: number }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[]) {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(CircuitRenderer.getWireWeight(startInfo.bitWidth));
        p.noFill();
        const cpOffset = GRID_SIZE * 0.5;
        const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
        let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
        if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
        else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };

        p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    const inputs = dims.inputs;
    const outputs = dims.outputs;

    p.push();
    p.translate(comp.x, comp.y);

    if (comp.type === ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawIC(p, comp, w, h, library);
    } else if (comp.type === ComponentType.SPLITTER) {
        CircuitRenderer.drawSplitter(p, comp, w, h);
    } else if (comp.type === ComponentType.MERGER) {
        CircuitRenderer.drawMerger(p, comp, w, h);
    } else if (comp.type === ComponentType.INPUT_SWITCH) {
        CircuitRenderer.drawSwitch(p, comp, w, h);
    } else if (comp.type === ComponentType.OUTPUT_LED) {
        CircuitRenderer.drawLED(p, comp, w, h);
    } else if (comp.type === ComponentType.HEX_DISPLAY) {
        CircuitRenderer.drawHex(p, comp, w, h);
    } else {
        CircuitRenderer.drawGate(p, comp, w, h);
    }

    if (comp.type !== ComponentType.CUSTOM_IC) {
        CircuitRenderer.drawLabels(p, comp, w, h);
    }

    if (!['IC','INPUT','OUTPUT','HEX','SPLIT','MERGE'].includes(comp.type)) {
        p.noStroke(); p.fill('#64748b');
        for (let i = 0; i < inputs; i++) p.circle(0, ((i+1) * (h/(inputs+1))), 4);
        for (let i = 0; i < outputs; i++) p.circle(w, ((i+1) * (h/(outputs+1))), 4);
    }

    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(2);
        p.rect(-4, -4, w + 8, h + 8, 4);

        p.noStroke(); p.fill('#3b82f6');
        p.textSize(10); p.textAlign(p.RIGHT, p.TOP);
        p.text(`w:${comp.bitWidth}`, w + 4, h + 6);
    } else if (comp.bitWidth > 1) {
        p.noStroke(); p.fill('#94a3b8');
        p.textSize(9); p.textAlign(p.RIGHT, p.BOTTOM);
        p.text(comp.bitWidth, w - 2, h - 2);
    }

    p.pop();
  }

  static drawSelectionRect(p: p5Types, x: number, y: number, w: number, h: number) {
      // Normalize dimensions
      let rx = x;
      let ry = y;
      let rw = w;
      let rh = h;

      if (rw < 0) { rx += rw; rw = Math.abs(rw); }
      if (rh < 0) { ry += rh; rh = Math.abs(rh); }

      p.noStroke();
      p.fill(59, 130, 246, 30); // Blue-500 with low opacity
      p.rect(rx, ry, rw, rh);
      p.noFill();
      p.stroke(59, 130, 246, 150);
      p.strokeWeight(1);
      p.rect(rx, ry, rw, rh);
  }

  // --- Helper: Draw Fitted Text with Ellipsis ---
  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 12; 
      const minFontSize = 8;
      p.textSize(fontSize);
      p.textAlign(p.CENTER, p.CENTER);

      let currentText = text;
      let w = p.textWidth(currentText);

      if (w <= maxW) {
          p.text(currentText, x, y);
          return;
      }

      while (fontSize > minFontSize && w > maxW) {
          fontSize--;
          p.textSize(fontSize);
          w = p.textWidth(currentText);
      }

      if (w > maxW) {
          while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) {
              currentText = currentText.slice(0, -1);
          }
          currentText += '..';
      }

      p.text(currentText, x, y);
  }

  // --- Sub-Renderers ---

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, h * 0.3);
      p.vertex(w, 0);
      p.vertex(w, h);
      p.vertex(0, h * 0.7);
      p.endShape(p.CLOSE);

      p.fill('#64748b'); p.noStroke();
      p.circle(0, h/2, 5); 
      const step = h/3;
      p.circle(w, step, 4); 
      p.circle(w, step*2, 4); 

      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("/", w/2, h/2);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.beginShape();
      p.vertex(0, 0);
      p.vertex(w, h * 0.3);
      p.vertex(w, h * 0.7);
      p.vertex(0, h);
      p.endShape(p.CLOSE);

      p.fill('#64748b'); p.noStroke();
      const step = h/3;
      p.circle(0, step, 4); 
      p.circle(0, step*2, 4);
      p.circle(w, h/2, 5);

      p.fill('#0f172a'); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text("&", w/2, h/2);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.fill('#eff6ff'); 
    p.stroke('#3b82f6'); 
    p.strokeWeight(2);
    p.rect(0, 0, w, h, 6);

    p.fill('#1e3a8a'); 
    p.noStroke(); 
    p.textStyle(p.BOLD);

    const label = comp.customLabel || "IC";
    CircuitRenderer.drawFittedText(p, label, w/2, h/2, w - 4, h - 4);

    if (comp.functionId) {
        const funcDef = library.find(f => f.id === comp.functionId);
        if (funcDef) {
            const inputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true);
            const outputs = CircuitRenderer.sortICPorts(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

            const drawPort = (c: CircuitComponent, index: number, isInput: boolean) => {
                const pt = CircuitRenderer.getPortPosition(comp, index, isInput ? 'input' : 'output', library);
                const rx = pt.x - comp.x;
                const ry = pt.y - comp.y;

                p.fill(isInput ? '#3b82f6' : '#f59e0b');
                p.stroke('#1e293b'); p.strokeWeight(1);
                p.circle(rx, ry, 6);

                if (c.customLabel) {
                    p.noStroke();
                    p.fill('#334155');
                    p.textSize(8);
                    p.textStyle(p.NORMAL);

                    if (pt.side === 'left') {
                        p.textAlign(p.LEFT, p.CENTER);
                        p.text(c.customLabel, rx + 6, ry);
                    } else if (pt.side === 'right') {
                        p.textAlign(p.RIGHT, p.CENTER);
                        p.text(c.customLabel, rx - 6, ry);
                    } else if (pt.side === 'top') {
                         p.textAlign(p.CENTER, p.TOP);
                         p.text(c.customLabel, rx, ry + 6);
                    } else { 
                         p.textAlign(p.CENTER, p.BOTTOM);
                         p.text(c.customLabel, rx, ry - 6);
                    }
                }
            };

            inputs.forEach((c, i) => drawPort(c, i, true));
            outputs.forEach((c, i) => drawPort(c, i, false));
        }
    }
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      const side = comp.icPortSide || 'right';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = w, portY = h/2;
      if (side === 'left') { portX = 0; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      p.stroke(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_STROKE);
      p.fill(isOn ? COLOR_BUS_ON : COLOR_COMPONENT_BG);
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');

      if (comp.bitWidth >= 16) {
          p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
          p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
          const hex = "0x" + bitsToHex(comp.outputValues[0] || []);
          CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      } else {
          p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
          p.text(isOn ? "1" : "0", w/2, h/2);
      }
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      const side = comp.icPortSide || 'left';
      const boxSize = GRID_SIZE * 0.6;
      const boxOffset = (GRID_SIZE - boxSize) / 2;

      let portX = 0, portY = h/2;
      if (side === 'right') { portX = w; }
      else if (side === 'top') { portX = w/2; portY = 0; }
      else if (side === 'bottom') { portX = w/2; portY = h; }

      p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
      p.line(w/2, h/2, portX, portY);
      p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

      if (isOn) { p.noStroke(); p.fill(245, 158, 11, 80); p.rect(boxOffset-3, boxOffset-3, boxSize+6, boxSize+6, 6); }
      p.stroke(isOn ? COLOR_BUS_ON : '#334155');
      p.fill(isOn ? COLOR_BUS_ON : '#1e293b');
      p.rect(boxOffset, boxOffset, boxSize, boxSize, 4);

      p.noStroke(); p.fill(isOn ? '#fff' : '#475569');
      if (comp.bitWidth >= 16) {
           p.textSize(9); p.textAlign(p.CENTER, p.CENTER);
           p.text(`${comp.bitWidth}b`, w/2, h/2);
      } else if (comp.bitWidth > 1) {
           const hex = "0x" + bitsToHex(comp.inputValues[0] || []);
           CircuitRenderer.drawFittedText(p, hex, w/2, h/2, boxSize - 2, boxSize - 2);
      }
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const padX = 4;
      p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, 4, w - (padX*2), h-8, 4);
      p.noStroke(); p.fill('#ef4444'); 

      const hex = bitsToHex(comp.inputValues[0] || []);

      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - (padX*2) - 4, h - 12);

      p.fill('#64748b'); p.circle(0, h/2, 5);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    const py = 6;
    const gateW = w - 10;
    const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
    const bubbleR = 4;
    let bodyW = isNegated ? gateW - (bubbleR*2) : gateW;

    p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(2);
    p.line(gateW, h/2, w, h/2); 

    if (comp.type === 'NOT') {
        p.fill(COLOR_COMPONENT_BG);
        (p as any).triangle(0, py, 0, h - py, bodyW, h / 2);
    } else {
        const isXor = comp.type === 'XOR';
        const isOrFamily = ['OR', 'NOR', 'XOR'].includes(comp.type);
        let startX = 0;

        if (isXor) {
            startX = 5;
            p.noFill();
            p.beginShape(); p.vertex(0, py); (p as any).bezierVertex(3, h * 0.33, 3, h * 0.66, 0, h - py); p.endShape();
        }

        p.fill(COLOR_COMPONENT_BG);
        p.beginShape();
        if (isOrFamily) {
            p.vertex(startX, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(startX, h - py);
            (p as any).bezierVertex(startX + 5, h * 0.75, startX + 5, h * 0.25, startX, py);
        } else {
            p.vertex(0, py); p.vertex(bodyW * 0.5, py);
            (p as any).bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py);
            p.vertex(0, h - py); p.vertex(0, py);
        }
        p.endShape(p.CLOSE);
    }

    if (isNegated) {
        p.fill(COLOR_COMPONENT_BG); p.circle(gateW - bubbleR, h / 2, bubbleR*2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
        p.noStroke(); p.fill('#1e293b'); p.textSize(12); p.textStyle(p.BOLD);
        p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
        p.textStyle(p.NORMAL);
      }
  }
}

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import Toolbar from './components/Toolbar';
import Modal from './components/Modal';
import { ComponentType, CircuitComponent } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  // CURSOR: Smart mode (Move/Edit + Desktop Box Select + Mobile Pan)
  // REGION: Force Box Selection
  // DELETE: Delete mode
  const [selectedTool, setSelectedTool] = useState<'CURSOR' | 'REGION' | 'DELETE'>('CURSOR');

  const [isPlaying, setIsPlaying] = useState(false);
  const [speedSlider, setSpeedSlider] = useState(90); 
  const [selectedBitWidth, setSelectedBitWidth] = useState<number>(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");

  // -- Component Selection --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- Drag & Drop State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string, bitWidth: number} | null>(null);

  // Ref to track drag position without triggering re-renders or stale closures in event handlers
  const dragPosRef = useRef<{x: number, y: number} | null>(null);

  // -- Refs --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Hooks --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // Computed Values
  const tickSpeed = speedSlider === 100 ? 0 : Math.max(1, 500 - (speedSlider * 5));
  const speedLabel = speedSlider === 100 ? "MAX" : `${tickSpeed}ms`;

  // -- Interaction Handlers --

  const handleTouchStartItem = (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => {
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos(pos);
    dragPosRef.current = pos;
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        const newPos = { x: touch.clientX, y: touch.clientY };
        setDragPos(newPos);
        dragPosRef.current = newPos;
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      const finalPos = dragPosRef.current;
      if (draggedType && finalPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          finalPos.x >= rect.left && finalPos.x <= rect.right &&
          finalPos.y >= rect.top && finalPos.y <= rect.bottom
        ) {
          setPendingDrop({ 
            type: draggedType, 
            x: finalPos.x - rect.left, 
            y: finalPos.y - rect.top, 
            functionId: draggedFuncId, 
            bitWidth: selectedBitWidth 
          });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
      dragPosRef.current = null;
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, draggedFuncId, selectedBitWidth]);

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      setTempLabel(comp?.customLabel || "");
  };

  // Poll for Simulation Updates (Live Monitor)
  const selectedIdRef = useRef<string | null>(null);
  useEffect(() => { selectedIdRef.current = selectedComponent?.id || null; }, [selectedComponent]);

  useEffect(() => {
      if (!isPlaying) return;
      const interval = setInterval(() => {
          const currentId = selectedIdRef.current;
          if (!currentId || !canvasRef.current) return;

          const { components } = canvasRef.current.getData();
          const freshComp = components.find(c => c.id === currentId);

          if (freshComp) {
              setSelectedComponent(prev => {
                  if (!prev || prev.id !== currentId) return prev;
                  // Optimization: Only update React state if logic state changed
                  const prevHash = JSON.stringify({ i: prev.inputValues, o: prev.outputValues });
                  const newHash = JSON.stringify({ i: freshComp.inputValues, o: freshComp.outputValues });
                  return prevHash !== newHash ? { ...freshComp } : prev;
              });
          }
      }, 100);
      return () => clearInterval(interval);
  }, [isPlaying]); 

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        selectedBitWidth={selectedBitWidth}
        onSelectBitWidth={setSelectedBitWidth}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
        onCopy={() => canvasRef.current?.copy()}
        onPaste={() => canvasRef.current?.paste()}
        onSelectAll={() => canvasRef.current?.selectAll()}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">

        <Toolbar 
            activeFunctionId={activeFunctionId}
            functions={functions}
            isPlaying={isPlaying}
            speedSlider={speedSlider}
            speedLabel={speedLabel}
            selectedComponent={selectedComponent}
            tempLabel={tempLabel}
            lastSaved={lastSaved}
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onSpeedChange={setSpeedSlider}
            onFunctionChange={(id) => { setIsPlaying(false); switchToFunction(id); }}
            onAddFunction={() => setIsModalOpen(true)}
            onDeleteFunction={deleteFunction}
            onFocusComponent={() => selectedComponent && canvasRef.current?.focusComponent(selectedComponent.id)}
            onUpdateComponent={updateProp}
            onBitToggle={(idx) => {
                if (selectedComponent && canvasRef.current) {
                    const currentBus = selectedComponent.outputValues[0] || new Array(selectedComponent.bitWidth).fill(false);
                    canvasRef.current.setComponentOutputBit(selectedComponent.id, idx, !currentBus[idx]);
                    // Optimistic update
                    const newBus = [...currentBus]; newBus[idx] = !newBus[idx];
                    setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
                }
            }}
            onBatchBusChange={(newBus) => {
                if (selectedComponent && canvasRef.current) {
                    canvasRef.current.updateSelectedComponent({ outputValues: [newBus] });
                    setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
                }
            }}
            onLabelChange={(val) => { setTempLabel(val); updateProp({ customLabel: val }); }}
            onSave={persist}
            onImport={() => fileInputRef.current?.click()}
            onExportProject={() => handleExport('PROJECT')}
            onExportFunction={() => handleExport('FUNCTION')}
            onClear={() => { if(confirm("Clear all data?")) clearData(); }}
        />

        {/* Main Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost Visual */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-90" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-white border-2 border-blue-500 rounded-lg flex items-center justify-center shadow-2xl">
              <span className="text-[10px] font-bold text-slate-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label.substring(0,3)}</span>
              <span className="absolute -top-2 -right-2 bg-blue-600 text-white text-[9px] w-5 h-5 flex items-center justify-center rounded-full shadow-sm">{selectedBitWidth}</span>
            </div>
          </div>
        )}

        <Modal 
            isOpen={isModalOpen}
            title="Create New Function"
            onClose={() => setIsModalOpen(false)}
            onSubmit={() => {
                if (newFuncName.trim()) {
                    addFunction(newFuncName);
                    setNewFuncName("");
                    setIsModalOpen(false);
                }
            }}
        >
             <input 
                autoFocus 
                type="text" 
                value={newFuncName} 
                onChange={(e) => setNewFuncName(e.target.value)} 
                placeholder="Function Name (e.g., Full Adder)" 
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-blue-400 outline-none transition-all" 
            />
        </Modal>

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ComponentType, FunctionCircuit } from '../types';
import { COMPONENT_DEFINITIONS, VALID_BIT_WIDTHS } from '../constants';
import DraggableItem from './DraggableItem';

interface SidebarProps {
  selectedTool: 'CURSOR' | 'REGION' | 'DELETE';
  onSelectTool: (t: 'CURSOR' | 'REGION' | 'DELETE') => void;
  selectedBitWidth: number;
  onSelectBitWidth: (w: number) => void;
  onTouchStartItem?: (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => void;
  functionLibrary: FunctionCircuit[];
  // Clipboard actions
  onCopy: () => void;
  onPaste: () => void;
  onSelectAll: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
    selectedTool, 
    onSelectTool, 
    selectedBitWidth, 
    onSelectBitWidth,
    onTouchStartItem, 
    functionLibrary,
    onCopy,
    onPaste,
    onSelectAll
}) => {
  const [searchTerm, setSearchTerm] = useState("");

  const groups = [
    { name: 'Bus Tools', items: [ComponentType.SPLITTER, ComponentType.MERGER] },
    { name: 'I/O', items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.HEX_DISPLAY] },
    { name: 'Gates', items: [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR] }
  ];

  // Search Logic
  const filteredGroups = groups.map(group => ({
    ...group,
    items: group.items.filter(type => {
        if (!searchTerm) return true;
        const def = COMPONENT_DEFINITIONS[type];
        const lowerTerm = searchTerm.toLowerCase();
        return def.label.toLowerCase().includes(lowerTerm) || 
               def.description.toLowerCase().includes(lowerTerm) ||
               type.toLowerCase().includes(lowerTerm);
    })
  })).filter(g => g.items.length > 0);

  const filteredFunctions = functionLibrary.filter(f => 
      f.id !== 'main' && 
      (searchTerm ? f.name.toLowerCase().includes(searchTerm.toLowerCase()) : true)
  );

  return (
    <div className="w-64 bg-white border-r border-slate-200 flex flex-col h-full shadow-lg z-10">
      <div className="p-4 border-b border-slate-100 bg-slate-50/50">
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">LogicFlow</h1>
        <p className="text-xs text-slate-400 mt-1">Bus Width Simulator</p>
      </div>

      <div className="p-3 border-b border-slate-50">
        <div className="relative">
            <span className="absolute left-2.5 top-1.5 text-slate-400 text-sm">🔍</span>
            <input 
                type="text"
                placeholder="Search components..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-8 pr-3 py-1.5 text-sm bg-slate-100 border-transparent focus:bg-white border focus:border-blue-300 rounded-md outline-none transition-all placeholder-slate-400 text-slate-700"
            />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 overscroll-contain scrollbar-thin">

        {/* Tools Section */}
        <section>
          <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">Tools</h3>
          <div className="grid grid-cols-3 gap-2 mb-3">
            <button
              onClick={() => onSelectTool('CURSOR')}
              className={`p-2 rounded text-xs font-bold transition-colors flex flex-col items-center justify-center gap-1 ${selectedTool === 'CURSOR' ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title="Move / Edit (Default)"
            >
              <span className="text-base">👆</span> Move
            </button>
            <button
              onClick={() => onSelectTool('REGION')}
              className={`p-2 rounded text-xs font-bold transition-colors flex flex-col items-center justify-center gap-1 ${selectedTool === 'REGION' ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title="Area Selection Only"
            >
              <span className="text-base">⛶</span> Area
            </button>
            <button
              onClick={() => onSelectTool('DELETE')}
              className={`p-2 rounded text-xs font-bold transition-colors flex flex-col items-center justify-center gap-1 ${selectedTool === 'DELETE' ? 'bg-red-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title="Delete Item"
            >
              <span className="text-base">🗑️</span> Del
            </button>
          </div>

          {/* Clipboard Actions for Touch Users */}
          <div className="grid grid-cols-3 gap-2">
             <button onClick={onCopy} className="py-1.5 px-2 bg-white border border-slate-200 rounded text-xs font-medium text-slate-600 hover:bg-slate-50 active:scale-95 transition-transform" title="Copy">
                📋 Copy
             </button>
             <button onClick={onPaste} className="py-1.5 px-2 bg-white border border-slate-200 rounded text-xs font-medium text-slate-600 hover:bg-slate-50 active:scale-95 transition-transform" title="Paste">
                📝 Paste
             </button>
             <button onClick={onSelectAll} className="py-1.5 px-2 bg-white border border-slate-200 rounded text-xs font-medium text-slate-600 hover:bg-slate-50 active:scale-95 transition-transform" title="Select All">
                ✅ All
             </button>
          </div>
        </section>

        {/* Bit Width Section */}
        <section>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 pl-1">Bus Width</h3>
            <div className="flex flex-wrap gap-1.5">
                {VALID_BIT_WIDTHS.map(w => (
                    <button
                        key={w}
                        onClick={() => onSelectBitWidth(w)}
                        className={`px-2.5 py-1 text-xs font-bold rounded border transition-all ${selectedBitWidth === w 
                            ? 'bg-blue-100 border-blue-400 text-blue-700 shadow-sm scale-105' 
                            : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                    >
                        {w}
                    </button>
                ))}
            </div>
        </section>

        {/* Component Groups */}
        {filteredGroups.map(group => (
          <section key={group.name}>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">{group.name}</h3>
            <div className="grid grid-cols-2 gap-3">
              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                const disabled = (type === ComponentType.SPLITTER || type === ComponentType.MERGER) && selectedBitWidth < 2;
                const subLabel = type === ComponentType.SPLITTER ? `${selectedBitWidth}→${selectedBitWidth/2}` : 
                                 type === ComponentType.MERGER ? `${selectedBitWidth/2}→${selectedBitWidth}` : 
                                 `x${selectedBitWidth}`;

                return (
                   <DraggableItem 
                        key={type}
                        type={type}
                        label={def.label}
                        subLabel={subLabel}
                        disabled={disabled}
                        bitWidth={selectedBitWidth}
                        onTouchStartItem={onTouchStartItem}
                   />
                );
              })}
            </div>
          </section>
        ))}

        {/* Custom Functions Section */}
        {(filteredFunctions.length > 0 || (searchTerm && filteredFunctions.length === 0)) && (
            <section>
                 <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">My Functions</h3>
                 {filteredFunctions.length > 0 ? (
                     <div className="grid grid-cols-1 gap-2">
                        {filteredFunctions.map(func => (
                            <DraggableItem
                                key={func.id}
                                type={ComponentType.CUSTOM_IC}
                                label={func.name}
                                subLabel=""
                                disabled={false}
                                bitWidth={selectedBitWidth}
                                functionId={func.id}
                                isCustom={true}
                                onTouchStartItem={onTouchStartItem}
                            />
                        ))}
                     </div>
                 ) : (
                     <p className="text-xs text-slate-400 italic pl-1">No functions match search.</p>
                 )}
            </section>
        )}

      </div>
    </div>
  );
};

export default Sidebar;

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
  focusComponent: (compId: string) => void;
  copy: () => void;
  paste: () => void;
  selectAll: () => void;
}

interface LogicCanvasProps {
  tool: 'CURSOR' | 'REGION' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

interface SelectionBox {
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  active: boolean;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // State Refs
  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  const selectedCompIds = useRef<Set<string>>(new Set()); 
  const selectionBoxRef = useRef<SelectionBox>({ startX: 0, startY: 0, currentX: 0, currentY: 0, active: false });
  const clipboardRef = useRef<{ components: CircuitComponent[], wires: Wire[] } | null>(null);

  // Interaction State
  const activeDragIds = useRef<Set<string>>(new Set());
  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const hasDraggedRef = useRef<boolean>(false); 
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragStartPos = useRef<Point>({ x: 0, y: 0 }); 
  const accumTimeRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  // -- Clipboard Logic --
  const handleCopy = () => {
      if (selectedCompIds.current.size === 0) return;
      const selectedComps = componentsRef.current.filter(c => selectedCompIds.current.has(c.id));
      const internalWires = wiresRef.current.filter(w => 
          selectedCompIds.current.has(w.fromCompId) && selectedCompIds.current.has(w.toCompId)
      );

      clipboardRef.current = {
          components: JSON.parse(JSON.stringify(selectedComps)),
          wires: JSON.parse(JSON.stringify(internalWires))
      };
      console.log(`Copied ${selectedComps.length} items to clipboard`);
  };

  const handlePaste = () => {
      if (!clipboardRef.current) return;
      const { components: clipComps, wires: clipWires } = clipboardRef.current;
      clearSelection();
      const idMap = new Map<string, string>();
      const OFFSET = GRID_SIZE; 
      const newComps: CircuitComponent[] = clipComps.map(c => {
          const newId = crypto.randomUUID();
          idMap.set(c.id, newId);
          return { ...c, id: newId, x: c.x + OFFSET, y: c.y + OFFSET, inputValues: c.inputValues.map(v => []), outputValues: c.outputValues.map(v => []) };
      });
      const newWires: Wire[] = clipWires.map(w => ({
          ...w, id: crypto.randomUUID(), fromCompId: idMap.get(w.fromCompId)!, toCompId: idMap.get(w.toCompId)!, state: new Array(w.bitWidth).fill(false)
      }));
      componentsRef.current.push(...newComps);
      wiresRef.current.push(...newWires);
      newComps.forEach(c => selectedCompIds.current.add(c.id));
      if (newComps.length > 0 && onSelectionChange) onSelectionChange(newComps[newComps.length - 1]);
  };

  const handleSelectAll = () => {
      componentsRef.current.forEach(c => selectedCompIds.current.add(c.id));
      if (onSelectionChange && componentsRef.current.length > 0) onSelectionChange(componentsRef.current[componentsRef.current.length - 1]);
  };

  const handleDelete = () => {
     if (selectedCompIds.current.size === 0) return;
     const idsToDelete = selectedCompIds.current;
     componentsRef.current = componentsRef.current.filter(c => !idsToDelete.has(c.id));
     wiresRef.current = wiresRef.current.filter(w => !idsToDelete.has(w.fromCompId) && !idsToDelete.has(w.toCompId));
     clearSelection();
  };

  useImperativeHandle(ref, () => ({
    getData: () => ({ components: componentsRef.current, wires: wiresRef.current }),
    updateSelectedComponent: (updates) => {
        let updatedCount = 0;
        componentsRef.current.forEach(c => {
            if (selectedCompIds.current.has(c.id)) { Object.assign(c, updates); updatedCount++; }
        });
        if (updatedCount > 0 && onSelectionChange) {
             const lastId = Array.from(selectedCompIds.current).pop();
             const comp = componentsRef.current.find(c => c.id === lastId) || null;
             onSelectionChange(comp); 
        }
    },
    deleteSelected: handleDelete,
    setComponentOutputBit: (compId, bitIndex, value) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) while(currentBus.length < comp.bitWidth) currentBus.push(false);
            const newBus = [...currentBus]; newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    },
    focusComponent: (compId) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && containerRef.current) {
             const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
             const cx = comp.x + (dims.w * GRID_SIZE)/2;
             const cy = comp.y + (dims.h * GRID_SIZE)/2;
             const sw = containerRef.current.clientWidth;
             const sh = containerRef.current.clientHeight;
             viewportRef.current.x = (sw/2) - (cx * viewportRef.current.zoom);
             viewportRef.current.y = (sh/2) - (cy * viewportRef.current.zoom);
        }
    },
    copy: handleCopy, paste: handlePaste, selectAll: handleSelectAll
  }));

  const screenToWorld = (sx: number, sy: number): Point => ({
    x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
    y: (sy - viewportRef.current.y) / viewportRef.current.zoom
  });

  const clearSelection = () => { selectedCompIds.current.clear(); if (onSelectionChange) onSelectionChange(null); };
  const addToSelection = (id: string) => { selectedCompIds.current.add(id); const comp = componentsRef.current.find(c => c.id === id) || null; if (onSelectionChange) onSelectionChange(comp); };
  const toggleSelection = (id: string) => {
    if (selectedCompIds.current.has(id)) { selectedCompIds.current.delete(id); if (onSelectionChange) onSelectionChange(null); } 
    else { selectedCompIds.current.add(id); const comp = componentsRef.current.find(c => c.id === id) || null; if (onSelectionChange) onSelectionChange(comp); }
  };

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement) return;
          const key = e.key.toLowerCase(); const ctrl = e.ctrlKey || e.metaKey;
          if (key === 'delete' || key === 'backspace') handleDelete();
          else if (ctrl && key === 'c') handleCopy();
          else if (ctrl && key === 'v') handlePaste();
          else if (ctrl && key === 'a') { e.preventDefault(); handleSelectAll(); }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;
    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs; outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = { components: JSON.parse(JSON.stringify(func.components)), wires: JSON.parse(JSON.stringify(func.wires)) };
        }
    }
    const newComp: CircuitComponent = {
      id: crypto.randomUUID(), type: type, x: snapX, y: snapY,
      inputValues: new Array(inputsCount).fill([]), outputValues: new Array(outputsCount).fill([]),
      functionId: functionId, internalState: internalState, customLabel: type === ComponentType.CUSTOM_IC ? label : undefined, bitWidth: bitWidth
    };
    componentsRef.current.push(newComp);
    clearSelection(); addToSelection(newComp.id);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      if (comp.type === ComponentType.SPLITTER) return type === 'input' ? comp.bitWidth : comp.bitWidth / 2;
      if (comp.type === ComponentType.MERGER) return type === 'output' ? comp.bitWidth : comp.bitWidth / 2; 
      return comp.bitWidth;
  };

  // --- P5.js Sketch ---
  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;
      let isRightMousePressed = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);
        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components; wiresRef.current = result.wires;
              }
              accumTimeRef.current = 0;
          } else {
              accumTimeRef.current += p.deltaTime;
              if (accumTimeRef.current > 500) accumTimeRef.current = 500; 
              while (accumTimeRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components; wiresRef.current = result.wires;
                accumTimeRef.current -= speed;
              }
          }
        } else accumTimeRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, selectedCompIds.current.has(comp.id));
        });

        if (selectionBoxRef.current.active) {
            CircuitRenderer.drawSelectionRect(p, 
                selectionBoxRef.current.startX, 
                selectionBoxRef.current.startY, 
                selectionBoxRef.current.currentX - selectionBoxRef.current.startX, 
                selectionBoxRef.current.currentY - selectionBoxRef.current.startY
            );
        }

        if (!isDraggingComp.current && !selectionBoxRef.current.active) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; 
                        else if (wiringStart.current.type === hPort.type) isValid = false; 
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false;
                    }
                    p.noFill(); p.stroke(isValid ? '#3b82f6' : '#ef4444'); p.strokeWeight(2); p.circle(pos.x, pos.y, 14);
                }
            }
        }
        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (let i = componentsRef.current.length - 1; i >= 0; i--) {
          const comp = componentsRef.current[i];
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // --- Interaction Logic ---

      const handleDragMove = (dx: number, dy: number, currentX: number, currentY: number, isTouch: boolean) => {
          if (Math.abs(dx) > 0 || Math.abs(dy) > 0) hasDraggedRef.current = true;

          const mouseWorld = screenToWorld(currentX, currentY);

          if (isPanningRef.current) {
              // Explicit Pan state (Space/RightClick)
              viewportRef.current.x += dx;
              viewportRef.current.y += dy;
          } else if (isDraggingComp.current && activeDragIds.current.size > 0) {
              // Moving Object
              componentsRef.current.forEach(c => {
                  if (activeDragIds.current.has(c.id)) {
                      c.x += dx / viewportRef.current.zoom;
                      c.y += dy / viewportRef.current.zoom;
                  }
              });
              dragStartPos.current = mouseWorld;
          } else if (selectionBoxRef.current.active) {
              // Updating Selection Box
              selectionBoxRef.current.currentX = mouseWorld.x;
              selectionBoxRef.current.currentY = mouseWorld.y;
          } else if (isTouch) {
              // Touch on Background (No explicit state yet)
              if (toolRef.current === 'REGION') {
                  // If REGION mode, treat touch background as selection box update
                  // But usually selection box starts in touchStart. 
                  // If we are here, it means we missed start or logic flow.
                  // For robust Box Select on touch, we should rely on selectionBox.active
              } else {
                  // CURSOR mode on Touch Background -> PAN
                  viewportRef.current.x += dx;
                  viewportRef.current.y += dy;
              }
          }
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;

        hasDraggedRef.current = false;

        isRightMousePressed = (p.mouseButton === p.RIGHT) || p.keyIsDown(p.CONTROL); 
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Pan with Right Click or Space (regardless of tool)
        if (isRightMousePressed || p.keyIsDown(32)) { 
             isPanningRef.current = true;
             return;
        }

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            // Handle wiring ...
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
            wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
            return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
            if (toolRef.current === 'DELETE') {
                 selectedCompIds.current.clear();
                 selectedCompIds.current.add(compId);
                 handleDelete();
                 return;
            }

            if (p.keyIsDown(p.SHIFT)) {
                toggleSelection(compId);
            } else if (!selectedCompIds.current.has(compId)) {
                clearSelection();
                addToSelection(compId);
            }

            if (selectedCompIds.current.has(compId)) {
                 isDraggingComp.current = true;
                 dragStartPos.current = { x: mouseWorld.x, y: mouseWorld.y };
                 activeDragIds.current = new Set(selectedCompIds.current);
            }
            return;
        }

        // Background Click Logic
        if (!wiringStart.current) {
            if (toolRef.current === 'REGION') {
                // REGION mode: Always Box Select
                clearSelection();
                selectionBoxRef.current = {
                    startX: mouseWorld.x, startY: mouseWorld.y,
                    currentX: mouseWorld.x, currentY: mouseWorld.y,
                    active: true
                };
            } else if (toolRef.current === 'CURSOR') {
                 // CURSOR mode on Desktop (Mouse): Box Select
                 // (Touch is handled in touchStarted/Moved for Pan)
                 // If we are here, it's mousePressed.
                 // We assume Mouse = Box Select. Touch = Pan.
                 // But p.mousePressed fires for Touch too.
                 // We rely on touchStarted setting a flag, or checks.
                 // Simple approach: If not touch, Box Select.
                 if (p.touches.length === 0) {
                    clearSelection();
                    selectionBoxRef.current = {
                        startX: mouseWorld.x, startY: mouseWorld.y,
                        currentX: mouseWorld.x, currentY: mouseWorld.y,
                        active: true
                    };
                 }
            }
        }
      };

      p.mouseDragged = () => {
        if (p.touches.length === 0) {
            handleDragMove(p.mouseX - p.pmouseX, p.mouseY - p.pmouseY, p.mouseX, p.mouseY, false);
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Snap to Grid
        if (isDraggingComp.current) {
            componentsRef.current.forEach(c => {
                if (activeDragIds.current.has(c.id)) {
                    c.x = Math.round(c.x / GRID_SIZE) * GRID_SIZE;
                    c.y = Math.round(c.y / GRID_SIZE) * GRID_SIZE;
                }
            });
        }

        // Click interaction
        if (!isPanningRef.current && !selectionBoxRef.current.active && !wiringStart.current) {
             const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
             if (compId && !isDraggingComp.current && !hasDraggedRef.current) {
                  const comp = componentsRef.current.find(c => c.id === compId);
                  if (comp && comp.type === ComponentType.INPUT_SWITCH && comp.bitWidth === 1) {
                        const val = comp.outputValues[0]?.[0] || false;
                        comp.outputValues[0] = new Array(comp.bitWidth).fill(!val);
                  }
             }
        }

        // Finalize Box Selection
        if (selectionBoxRef.current.active) {
            const bx = Math.min(selectionBoxRef.current.startX, selectionBoxRef.current.currentX);
            const by = Math.min(selectionBoxRef.current.startY, selectionBoxRef.current.currentY);
            const bw = Math.abs(selectionBoxRef.current.currentX - selectionBoxRef.current.startX);
            const bh = Math.abs(selectionBoxRef.current.currentY - selectionBoxRef.current.startY);

            if (bw > 2 || bh > 2) {
                componentsRef.current.forEach(c => {
                    const dims = CircuitRenderer.getComponentDimensions(c, libraryRef.current);
                    const cw = dims.w * GRID_SIZE;
                    const ch = dims.h * GRID_SIZE;
                    if (c.x < bx + bw && c.x + cw > bx && c.y < by + bh && c.y + ch > by) {
                        selectedCompIds.current.add(c.id);
                    }
                });
                if (selectedCompIds.current.size > 0 && onSelectionChange) {
                     const ids = Array.from(selectedCompIds.current);
                     const last = componentsRef.current.find(c => c.id === ids[ids.length-1]) || null;
                     onSelectionChange(last);
                }
            }
        }

        activeDragIds.current.clear();
        isDraggingComp.current = false;
        isPanningRef.current = false;
        selectionBoxRef.current.active = false;
        hasDraggedRef.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;
             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;
                if (src.type === 'output' && dst.type === 'input') {
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(), fromCompId: src.compId, fromPortIndex: src.portIndex, toCompId: dst.compId, toPortIndex: dst.portIndex,
                      state: new Array(wiringStart.current.bitWidth).fill(false), bitWidth: wiringStart.current.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };

      // --- Touch Support ---
      (p as any).touchStarted = (e: any) => { 
        if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } 
        isCanvasInteraction = true; 

        if (p.touches.length === 2) { 
             const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
             pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); 
        } else if (p.touches.length === 1) { 
             lastTouchX = (p.touches[0] as any).x; 
             lastTouchY = (p.touches[0] as any).y; 

             // Trigger Logic
             const mouseWorld = screenToWorld(lastTouchX, lastTouchY);
             const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
             const port = getHoveredPort(mouseWorld.x, mouseWorld.y);

             // If touching Component or Port, treat as interaction (wire/move)
             if (compId || port) {
                 p.mousePressed(undefined);
             } else {
                 // Background Touch
                 if (toolRef.current === 'REGION') {
                     // REGION Mode -> Box Select
                     p.mousePressed(undefined); // triggers box select logic
                 } else {
                     // CURSOR Mode -> Pan (Do not trigger mousePressed, which sets Box Select)
                     // We just let touchMoved handle the Pan.
                 }
             }
        } 
        return false; 
      };

      (p as any).touchMoved = (e: any) => { 
        if (!isCanvasInteraction) return true; 

        if (p.touches.length === 2) { 
            // Zoom logic ...
             const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
            const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); 
            if (pinchDistStart > 0) { 
                const scaleFactor = currentDist / pinchDistStart; 
                const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); 
                const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; 
                const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; 
                const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; 
                viewportRef.current.zoom = newZoom; 
                viewportRef.current.x = cx - wx * newZoom; 
                viewportRef.current.y = cy - wy * newZoom; 
                pinchDistStart = currentDist; 
            } 
        } else if (p.touches.length === 1) { 
            const tx = (p.touches[0] as any).x;
            const ty = (p.touches[0] as any).y;
            const dx = tx - lastTouchX;
            const dy = ty - lastTouchY;

            handleDragMove(dx, dy, tx, ty, true);

            lastTouchX = tx; 
            lastTouchY = ty; 
        } 
        return false; 
      };

      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        if (e.target !== (p as any).canvas) return true;
        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
      tabIndex={0} 
    />
  );
});

export default LogicCanvas;

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
  focusComponent: (compId: string) => void;
  copy: () => void;
  paste: () => void;
  selectAll: () => void;
}

interface LogicCanvasProps {
  tool: 'CURSOR' | 'REGION' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

interface SelectionBox {
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  active: boolean;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // State Refs
  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  const selectedCompIds = useRef<Set<string>>(new Set()); 
  const selectionBoxRef = useRef<SelectionBox>({ startX: 0, startY: 0, currentX: 0, currentY: 0, active: false });
  const clipboardRef = useRef<{ components: CircuitComponent[], wires: Wire[] } | null>(null);

  // Interaction State
  const activeDragIds = useRef<Set<string>>(new Set());
  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const hasDraggedRef = useRef<boolean>(false); 
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragStartPos = useRef<Point>({ x: 0, y: 0 }); 
  const accumTimeRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  // -- Clipboard Logic --
  const handleCopy = () => {
      if (selectedCompIds.current.size === 0) return;
      const selectedComps = componentsRef.current.filter(c => selectedCompIds.current.has(c.id));
      const internalWires = wiresRef.current.filter(w => 
          selectedCompIds.current.has(w.fromCompId) && selectedCompIds.current.has(w.toCompId)
      );

      clipboardRef.current = {
          components: JSON.parse(JSON.stringify(selectedComps)),
          wires: JSON.parse(JSON.stringify(internalWires))
      };
      console.log(`Copied ${selectedComps.length} items to clipboard`);
  };

  const handlePaste = () => {
      if (!clipboardRef.current) return;
      const { components: clipComps, wires: clipWires } = clipboardRef.current;
      clearSelection();
      const idMap = new Map<string, string>();
      const OFFSET = GRID_SIZE; 
      const newComps: CircuitComponent[] = clipComps.map(c => {
          const newId = crypto.randomUUID();
          idMap.set(c.id, newId);
          return { ...c, id: newId, x: c.x + OFFSET, y: c.y + OFFSET, inputValues: c.inputValues.map(v => []), outputValues: c.outputValues.map(v => []) };
      });
      const newWires: Wire[] = clipWires.map(w => ({
          ...w, id: crypto.randomUUID(), fromCompId: idMap.get(w.fromCompId)!, toCompId: idMap.get(w.toCompId)!, state: new Array(w.bitWidth).fill(false)
      }));
      componentsRef.current.push(...newComps);
      wiresRef.current.push(...newWires);
      newComps.forEach(c => selectedCompIds.current.add(c.id));
      if (newComps.length > 0 && onSelectionChange) onSelectionChange(newComps[newComps.length - 1]);
  };

  const handleSelectAll = () => {
      componentsRef.current.forEach(c => selectedCompIds.current.add(c.id));
      if (onSelectionChange && componentsRef.current.length > 0) onSelectionChange(componentsRef.current[componentsRef.current.length - 1]);
  };

  const handleDelete = () => {
     if (selectedCompIds.current.size === 0) return;
     const idsToDelete = selectedCompIds.current;
     componentsRef.current = componentsRef.current.filter(c => !idsToDelete.has(c.id));
     wiresRef.current = wiresRef.current.filter(w => !idsToDelete.has(w.fromCompId) && !idsToDelete.has(w.toCompId));
     clearSelection();
  };

  useImperativeHandle(ref, () => ({
    getData: () => ({ components: componentsRef.current, wires: wiresRef.current }),
    updateSelectedComponent: (updates) => {
        let updatedCount = 0;
        componentsRef.current.forEach(c => {
            if (selectedCompIds.current.has(c.id)) { Object.assign(c, updates); updatedCount++; }
        });
        if (updatedCount > 0 && onSelectionChange) {
             const lastId = Array.from(selectedCompIds.current).pop();
             const comp = componentsRef.current.find(c => c.id === lastId) || null;
             onSelectionChange(comp); 
        }
    },
    deleteSelected: handleDelete,
    setComponentOutputBit: (compId, bitIndex, value) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) while(currentBus.length < comp.bitWidth) currentBus.push(false);
            const newBus = [...currentBus]; newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    },
    focusComponent: (compId) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && containerRef.current) {
             const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
             const cx = comp.x + (dims.w * GRID_SIZE)/2;
             const cy = comp.y + (dims.h * GRID_SIZE)/2;
             const sw = containerRef.current.clientWidth;
             const sh = containerRef.current.clientHeight;
             viewportRef.current.x = (sw/2) - (cx * viewportRef.current.zoom);
             viewportRef.current.y = (sh/2) - (cy * viewportRef.current.zoom);
        }
    },
    copy: handleCopy, paste: handlePaste, selectAll: handleSelectAll
  }));

  const screenToWorld = (sx: number, sy: number): Point => ({
    x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
    y: (sy - viewportRef.current.y) / viewportRef.current.zoom
  });

  const clearSelection = () => { selectedCompIds.current.clear(); if (onSelectionChange) onSelectionChange(null); };
  const addToSelection = (id: string) => { selectedCompIds.current.add(id); const comp = componentsRef.current.find(c => c.id === id) || null; if (onSelectionChange) onSelectionChange(comp); };
  const toggleSelection = (id: string) => {
    if (selectedCompIds.current.has(id)) { selectedCompIds.current.delete(id); if (onSelectionChange) onSelectionChange(null); } 
    else { selectedCompIds.current.add(id); const comp = componentsRef.current.find(c => c.id === id) || null; if (onSelectionChange) onSelectionChange(comp); }
  };

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement) return;
          const key = e.key.toLowerCase(); const ctrl = e.ctrlKey || e.metaKey;
          if (key === 'delete' || key === 'backspace') handleDelete();
          else if (ctrl && key === 'c') handleCopy();
          else if (ctrl && key === 'v') handlePaste();
          else if (ctrl && key === 'a') { e.preventDefault(); handleSelectAll(); }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;
    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs; outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            internalState = { components: JSON.parse(JSON.stringify(func.components)), wires: JSON.parse(JSON.stringify(func.wires)) };
        }
    }
    const newComp: CircuitComponent = {
      id: crypto.randomUUID(), type: type, x: snapX, y: snapY,
      inputValues: new Array(inputsCount).fill([]), outputValues: new Array(outputsCount).fill([]),
      functionId: functionId, internalState: internalState, customLabel: type === ComponentType.CUSTOM_IC ? label : undefined, bitWidth: bitWidth
    };
    componentsRef.current.push(newComp);
    clearSelection(); addToSelection(newComp.id);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      if (comp.type === ComponentType.SPLITTER) return type === 'input' ? comp.bitWidth : comp.bitWidth / 2;
      if (comp.type === ComponentType.MERGER) return type === 'output' ? comp.bitWidth : comp.bitWidth / 2; 
      return comp.bitWidth;
  };

  // --- P5.js Sketch ---
  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;
      let isRightMousePressed = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);
        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components; wiresRef.current = result.wires;
              }
              accumTimeRef.current = 0;
          } else {
              accumTimeRef.current += p.deltaTime;
              if (accumTimeRef.current > 500) accumTimeRef.current = 500; 
              while (accumTimeRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components; wiresRef.current = result.wires;
                accumTimeRef.current -= speed;
              }
          }
        } else accumTimeRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, selectedCompIds.current.has(comp.id));
        });

        if (selectionBoxRef.current.active) {
            CircuitRenderer.drawSelectionRect(p, 
                selectionBoxRef.current.startX, 
                selectionBoxRef.current.startY, 
                selectionBoxRef.current.currentX - selectionBoxRef.current.startX, 
                selectionBoxRef.current.currentY - selectionBoxRef.current.startY
            );
        }

        if (!isDraggingComp.current && !selectionBoxRef.current.active) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; 
                        else if (wiringStart.current.type === hPort.type) isValid = false; 
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false;
                    }
                    p.noFill(); p.stroke(isValid ? '#3b82f6' : '#ef4444'); p.strokeWeight(2); p.circle(pos.x, pos.y, 14);
                }
            }
        }
        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 15; // Increased hit radius for easier touch interaction
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (let i = componentsRef.current.length - 1; i >= 0; i--) {
          const comp = componentsRef.current[i];
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // --- Interaction Logic ---

      const handleDragMove = (dx: number, dy: number, currentX: number, currentY: number, isTouch: boolean) => {
          if (Math.abs(dx) > 0 || Math.abs(dy) > 0) hasDraggedRef.current = true;

          const mouseWorld = screenToWorld(currentX, currentY);

          if (isPanningRef.current) {
              // Explicit Pan state (Space/RightClick)
              viewportRef.current.x += dx;
              viewportRef.current.y += dy;
          } else if (isDraggingComp.current && activeDragIds.current.size > 0) {
              // Moving Object
              componentsRef.current.forEach(c => {
                  if (activeDragIds.current.has(c.id)) {
                      c.x += dx / viewportRef.current.zoom;
                      c.y += dy / viewportRef.current.zoom;
                  }
              });
              dragStartPos.current = mouseWorld;
          } else if (selectionBoxRef.current.active) {
              // Updating Selection Box
              selectionBoxRef.current.currentX = mouseWorld.x;
              selectionBoxRef.current.currentY = mouseWorld.y;
          } else if (isTouch) {
              // Touch on Background
              // CRITICAL FIX: Do not pan if we are in the middle of drawing a wire
              if (!wiringStart.current) {
                  if (toolRef.current === 'REGION') {
                      // REGION Mode -> treated as box select start usually, but if here...
                  } else {
                      // CURSOR Mode -> Pan
                      viewportRef.current.x += dx;
                      viewportRef.current.y += dy;
                  }
              }
          }
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;

        hasDraggedRef.current = false;

        isRightMousePressed = (p.mouseButton === p.RIGHT) || p.keyIsDown(p.CONTROL); 
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Pan with Right Click or Space (regardless of tool)
        if (isRightMousePressed || p.keyIsDown(32)) { 
             isPanningRef.current = true;
             return;
        }

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            // Handle wiring ...
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
            wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
            return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
            if (toolRef.current === 'DELETE') {
                 selectedCompIds.current.clear();
                 selectedCompIds.current.add(compId);
                 handleDelete();
                 return;
            }

            if (p.keyIsDown(p.SHIFT)) {
                toggleSelection(compId);
            } else if (!selectedCompIds.current.has(compId)) {
                clearSelection();
                addToSelection(compId);
            }

            if (selectedCompIds.current.has(compId)) {
                 isDraggingComp.current = true;
                 dragStartPos.current = { x: mouseWorld.x, y: mouseWorld.y };
                 activeDragIds.current = new Set(selectedCompIds.current);
            }
            return;
        }

        // Background Click Logic
        if (!wiringStart.current) {
            if (toolRef.current === 'REGION') {
                // REGION mode: Always Box Select
                clearSelection();
                selectionBoxRef.current = {
                    startX: mouseWorld.x, startY: mouseWorld.y,
                    currentX: mouseWorld.x, currentY: mouseWorld.y,
                    active: true
                };
            } else if (toolRef.current === 'CURSOR') {
                 // CURSOR mode on Desktop (Mouse): Box Select
                 // (Touch is handled in touchStarted/Moved for Pan)
                 // If we are here, it's mousePressed.
                 if (p.touches.length === 0) {
                    clearSelection();
                    selectionBoxRef.current = {
                        startX: mouseWorld.x, startY: mouseWorld.y,
                        currentX: mouseWorld.x, currentY: mouseWorld.y,
                        active: true
                    };
                 }
            }
        }
      };

      p.mouseDragged = () => {
        if (p.touches.length === 0) {
            handleDragMove(p.mouseX - p.pmouseX, p.mouseY - p.pmouseY, p.mouseX, p.mouseY, false);
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Snap to Grid
        if (isDraggingComp.current) {
            componentsRef.current.forEach(c => {
                if (activeDragIds.current.has(c.id)) {
                    c.x = Math.round(c.x / GRID_SIZE) * GRID_SIZE;
                    c.y = Math.round(c.y / GRID_SIZE) * GRID_SIZE;
                }
            });
        }

        // Click interaction
        if (!isPanningRef.current && !selectionBoxRef.current.active && !wiringStart.current) {
             const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
             if (compId && !isDraggingComp.current && !hasDraggedRef.current) {
                  const comp = componentsRef.current.find(c => c.id === compId);
                  if (comp && comp.type === ComponentType.INPUT_SWITCH && comp.bitWidth === 1) {
                        const val = comp.outputValues[0]?.[0] || false;
                        comp.outputValues[0] = new Array(comp.bitWidth).fill(!val);
                  }
             }
        }

        // Finalize Box Selection
        if (selectionBoxRef.current.active) {
            const bx = Math.min(selectionBoxRef.current.startX, selectionBoxRef.current.currentX);
            const by = Math.min(selectionBoxRef.current.startY, selectionBoxRef.current.currentY);
            const bw = Math.abs(selectionBoxRef.current.currentX - selectionBoxRef.current.startX);
            const bh = Math.abs(selectionBoxRef.current.currentY - selectionBoxRef.current.startY);

            if (bw > 2 || bh > 2) {
                componentsRef.current.forEach(c => {
                    const dims = CircuitRenderer.getComponentDimensions(c, libraryRef.current);
                    const cw = dims.w * GRID_SIZE;
                    const ch = dims.h * GRID_SIZE;
                    if (c.x < bx + bw && c.x + cw > bx && c.y < by + bh && c.y + ch > by) {
                        selectedCompIds.current.add(c.id);
                    }
                });
                if (selectedCompIds.current.size > 0 && onSelectionChange) {
                     const ids = Array.from(selectedCompIds.current);
                     const last = componentsRef.current.find(c => c.id === ids[ids.length-1]) || null;
                     onSelectionChange(last);
                }
            }
        }

        activeDragIds.current.clear();
        isDraggingComp.current = false;
        isPanningRef.current = false;
        selectionBoxRef.current.active = false;
        hasDraggedRef.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;
             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;
                if (src.type === 'output' && dst.type === 'input') {
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(), fromCompId: src.compId, fromPortIndex: src.portIndex, toCompId: dst.compId, toPortIndex: dst.portIndex,
                      state: new Array(wiringStart.current.bitWidth).fill(false), bitWidth: wiringStart.current.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };

      // --- Touch Support ---
      (p as any).touchStarted = (e: any) => { 
        if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } 
        isCanvasInteraction = true; 

        if (p.touches.length === 2) { 
             const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
             pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); 
        } else if (p.touches.length === 1) { 
             lastTouchX = (p.touches[0] as any).x; 
             lastTouchY = (p.touches[0] as any).y; 

             // Trigger Logic
             const mouseWorld = screenToWorld(lastTouchX, lastTouchY);
             const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
             const port = getHoveredPort(mouseWorld.x, mouseWorld.y);

             // If touching Component or Port, treat as interaction (wire/move)
             if (compId || port) {
                 p.mousePressed(undefined);
             } else {
                 // Background Touch
                 if (toolRef.current === 'REGION') {
                     // REGION Mode -> Box Select
                     p.mousePressed(undefined); 
                 } else {
                     // CURSOR Mode -> Pan
                     // Do not trigger mousePressed to avoid box select conflict
                 }
             }
        } 
        return false; 
      };

      (p as any).touchMoved = (e: any) => { 
        if (!isCanvasInteraction) return true; 

        if (p.touches.length === 2) { 
            // Zoom logic ...
             const t0 = p.touches[0] as any, t1 = p.touches[1] as any; 
            const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); 
            if (pinchDistStart > 0) { 
                const scaleFactor = currentDist / pinchDistStart; 
                const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); 
                const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; 
                const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; 
                const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; 
                viewportRef.current.zoom = newZoom; 
                viewportRef.current.x = cx - wx * newZoom; 
                viewportRef.current.y = cy - wy * newZoom; 
                pinchDistStart = currentDist; 
            } 
        } else if (p.touches.length === 1) { 
            const tx = (p.touches[0] as any).x;
            const ty = (p.touches[0] as any).y;
            const dx = tx - lastTouchX;
            const dy = ty - lastTouchY;

            handleDragMove(dx, dy, tx, ty, true);

            lastTouchX = tx; 
            lastTouchY = ty; 
        } 
        return false; 
      };

      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        if (e.target !== (p as any).canvas) return true;
        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
      tabIndex={0} 
    />
  );
});

export default LogicCanvas;
